window.BANK=window.BANK||{};window.BANK["2987"]={"n":"第三章 实践与认识及其发展规律","qs":[{"i":"66901","t":"单选","q":"“马者所以命形也；白者所以命色也。命色者非命形也，故曰白马非马。”从唯物辩证法的观点看，“白马非马” 这一命题的命题的错误在于（ ） ","o":{"A":"A.割裂了事物共性和个性之间的联系","B":" B.模糊了事物本质和现象之间的联系 ","C":"C.混淆了事物内容和形式之间的区别","D":" D.颠倒了事物形态和功能之间的关系 "},"a":"A","j":"<p>[难度系数]0.694本题考查的考点是：矛盾的普遍性和特殊性及相互关系。题干中的&ldquo;白马非马&rdquo;，是中国古代哲学家公孙龙的一个哲学命题，他的意思是&ldquo;马&rdquo;是对物&ldquo;形\"方面的规定，&ldquo;白马&rdquo;则是对马&ldquo;色&rdquo;方面的规定，对&ldquo;色&rdquo;方面的规定与对&ldquo;形&rdquo;方面的规定，自然是不同的。他割裂了两者的联系，割裂了共性和个性，普遍性和特殊性的联系。因此，正确选项是A。【干扰项辨识】选项B，C，D，并没有正确阐述&ldquo;白马&rdquo;与&ldquo;马&rdquo;之间的&ldquo;个别&rdquo;与&ldquo;一般&rdquo;的关系。因此，排除。必背金句：矛盾的普遍性和特殊性是辩证统一的关系。矛盾的普遍性即矛盾的共性，矛盾的特殊性即矛盾的个性。矛盾的共性是无条件的绝对的，矛盾的个性是有条件的、相对的。任何现实存在的事物都是共性和个性的有机统一，共性寓于个性之中，没有离开个性的共性，也没有离开共性的个性。</p>","k":"考点2 对立统一规律（唯物辩证法第一规律）","kid":"69","r":71370,"tot":82636},{"i":"66905","t":"单选","q":"《百喻经》中有一则寓言，有一个愚人到别人家去做客，他嫌菜没有味道，主人就给他加了点盐。菜里加了盐以后，味道好极了，愚人就想：“菜之所以鲜美，是因为有了盐，加一点点就如此鲜美，如果加更多的盐岂不是更加好吃?”回家以后，他把一把盐放进嘴里，结果又苦又咸，这则寓言给我们的启示是 ","o":{"A":"A.持续的量变会引起事物发生质的变化 ","B":"B.在认识和处理问题时要掌握适度的原则 ","C":"C.不可能通过一些现象而去认识某个事物的本质 ","D":"D.在事物的发展过程中要时时注意事物的自我否定"},"a":"B","j":"<p>[难度系数]0.877本题考查的考点是：量变、质变和度。度是保持事物质的稳定性的数量界限，即事物的范围、幅度和限度。度的两端叫关节点或临界点，超出度的范围，此物就转化为他物。度这一哲学范畴启示我们，在认识和处理问题时要掌握适度的原则。题干中，加点盐，味道好极了，但是当愚人将一把盐放进嘴里，结果就变得又苦又咸。启示我们做事要掌握适度的原则。因此，正确选项是B。【干扰项辨识】选项A，持续的量变只有超过了度的界限才会发生质变。因此，排除。选项C，现象和本质是统一的，所以我们能够通过现象认识事物的本质。因此，排除。选项D，题干中没有表述关于自我否定的内容。因此，排除。</p>","k":"考点3 量变质变规律（唯物辩证法第二规律）","kid":"143","r":64401,"tot":70893},{"i":"66912","t":"单选","q":"一位机械工程专家讲过这样一件事：“文革”中，他在农场劳动，有一天领导要他去割羊草。他没养过羊，怎么认得羊草呢？但脑子一转办法就来了。他把羊都赶去，看羊吃什么就割什么。不到半天就割回了羊草。这位专家之所以这样做是因为他意识到，“羊吃草”与“割羊草”两者之间存在着：","o":{"A":"A.主观联系","B":"B.必然联系","C":"C.因果联系","D":"D.本质联系"},"a":"C","j":"<p>[难度系数]0.459本题考查的考点是：原因与结果。原因和结果是揭示事物的前后相继.彼此制约的关系范畴。客观世界到处都存在着引起与被引起的普遍联系，辩证法把这种引起与被引起的关系称为因果关系。题干中，专家之所以能够在不认得羊草的情况下顺利完成任务，就在于他利用了&ldquo;羊吃草&rdquo;和&ldquo;割羊草&rdquo;之间的因果关系。虽然不认得羊应该吃什么样的草，但是通过观察羊吃什么样的草，来确定割什么样的草，找到&ldquo;羊吃草&rdquo;和&ldquo;割羊草&rdquo;之间是一种引起和被引起的关系。因此，正确选项是C。【干扰项辨识】选项A，唯物辩证法认为事物之间的联系是客观存在的，不是主观联系，因此，排除。选项B，必然联系指的是一种必须要发生，确定不移的关系。羊吃过的草，专家也可以不割。本题中的两种现象之间不符合必然联系。因此，排除。选项D，本质联系是指事物之间存在的内部的规律性的联系。&ldquo;羊吃草&rdquo;和&ldquo;割羊草&rdquo;指的均是两种现象，他们是现象之间的联系，而不是本质联系。因此，排除。必背金句：原因和结果的关系是辩证的：第一，原因和结果的区分既是确定的，又是不确定的。第二，原因和结果相互作用，原因产生结果，结果反过来影响原因，互为因果。第三，原因和结果互相渗透，结果存在于原因之中，原因表现在结果之中。第四，原因和结果的关系是复杂多样的，有一因多果、同因异果、一果多因.异因同果、多因多果、复合因果。</p>","k":"","kid":"","r":127179,"tot":214865},{"i":"66923","t":"单选","q":"中国工程院院士袁隆平曾结合自己的科研经历语重心长地对年轻人说:“书本知识非常重要，电脑技术也很重要，但是书本、电脑里面种不出水稻来，只有在田里才能种出水稻来。”这表明（  ）.","o":{"A":"A.实践是人类认识的基础和来源","B":"B.实践水平的提高有赖于认识水平的提高","C":"C.理论对实践的指导作用没有正确与错误之分","D":"D.由实践到认识的第一次飞跃比从认识到实践的第二次飞跃更重要"},"a":"A","j":"<p>题干中，袁隆平院士的话语凸显的是实践的重要性。书本、电脑里是种不出水稻的,只有在田里通过实践才能种出水稻。因此，<span style=\"background-color: #bfedd2;\"><strong>正确答案是A</strong></span>。</p>\n<p>干扰项辨识：</p>\n<p><strong>选项B</strong>，实践水平的提高会受到认识水平的影响，但不是依赖于认识水平的。因此，排除。</p>\n<p><strong>选项C</strong>，理论对实践的指导有正确和错误之分，正确的认识可以促进实践的发展，错误的认识会阻碍实 践的发展。因此，排除。</p>\n<p><strong>选项D</strong>，从认识到实践的第二次飞跃比从实践到认识的第一次飞跃更重要。因此，排除。</p>","k":"考点3 实践对认识的决定作用","kid":"73","r":184682,"tot":203675},{"i":"66928","t":"单选","q":"太空种水稻意义重大。“这说明在太空中种粮食是可行的。”不过，可别小瞧这趟旅行。“太空中的高真空宇宙射线、微重力等特殊环境，会让作物种子发生基因变异”王平举例，比如水稻种子在株高、生育期、米质、抗病性方面都可能产生突变。经研究发现，太空青椒比普通育椒的维生素C含量高 20% ；太空黄瓜不仅个头比普通黄瓜大，口感也更鲜嫩多汁；太空小番茄、太空西瓜的含糖量也比普通品种更高。这一事件告诉人们，实践的客体（  ）。","o":{"A":"A.是一切客观存在的事物","B":"B.是实践活动所指向的对象","C":"C.是主体所创造出来的对象","D":"D.有可能无法被人类所认识"},"a":"B","j":"<p>认识的客体是指实践活动所指向的对象。实践客体与客观存在的事物不完全等同，客观事物只有在被纳入主体实践活动的范围之内，为主体实践活动所指向并与主体相互作用时，才成为现实的实践客体。根据题干可知，实践活动是太空育种，实践的对象是水稻、青椒、小番茄、西瓜等。因此，<strong><span style=\"background-color: #bfedd2;\">正确答案是B</span></strong>。</p>\n<p>干扰项辨识：</p>\n<p><strong>选项A</strong>, 表述错误，实践客体与客观存在的事物不完全等同。</p>\n<p><strong>选项C</strong>，表述错误，实践的客体不是主体所创造出来的，因此，排除。</p>\n<p><strong>选项D,</strong> 表述错误，这是不可知论的观点。人类认识按其本性 来说，能够正确认识无限发展着的物质世界，这一点是无条件、绝对的。因此，排除。</p>","k":"考点2 实践的基本结构和形式","kid":"72","r":141401,"tot":203886},{"i":"66932","t":"单选","q":"银河系的直径为10万~18万光年，太阳系离银河系中心很远，且位置接近银道面，因此我们所看到的旋臂都重叠投影在天球上而无法分辨。近日，南京大学发布与美国科学家团队历经15年对银河系结构的研究成果，他们绘制出尺度为10万x 10万光年的全新银河系结构图。这张迄今最精确的银河系结构图清晰地展示出银河系是一个具有四条旋臂的棒旋星系，基本解决了银河系究竟有几条旋臂这个天文学中长期悬而未决的重大科学问题。这生动地说明了感性认识上升到理性认识的必要性在于（  ）。","o":{"A":"A.感性认识只反映事物的现象，理性认识反映事物的本质","B":"B.感性认识是认识的高级阶段，理性认识是认识的初级阶段","C":"C.感性认识是不可靠的，理性认识是可靠的","D":"D.感性认识来源于社会实践，理性认识来源于抽象思维"},"a":"A","j":"<p>感性认识是认识的低级阶段。感性认识的特点是直接性和具体性，这既是它的可靠性所在，也是它的局限性所在。感性认识的局限性是只反映了事物的现象、各个片面和外部联系，而认识的任务却要求把握事物的本质、全体和内部联系，这是认识过程中首先遇到的一个矛盾。要解决这个矛盾，必须实现由感性认识向理性认识的飞跃。理性认识是认识的高级阶段，理性认识的特点是它的间接性和抽象性。理性认识在形式上超越了客观事物，而在内容上则更深刻、更正确、更完整地反映了客观事物。这是它的特点和优点，但也造成了认识脱离现实的可能性。根据题干，科学家绘制结构图，从现象探寻本质，基本解决了科学问题，说明了感性认识只反映事物的现象，而理性认识反映事物的本质。因此，<span style=\"background-color: #bfedd2;\"><strong>正确答案是A</strong></span>。</p>\n<p>干扰项辨识：</p>\n<p><strong>选项B</strong>，表述错误，理性认识是认识的高级阶段，感性认识是认识的初级阶段。</p>\n<p><strong>选项C</strong>，表述错误，感性认识并不是不可靠，只是有一定局限性；理性认识也有可能造成认识脱离现实。</p>\n<p><strong>选项 D</strong>，表述错误，无论是感性认识还是理性认识，都是认识，实践才是认识的唯一来源。因此，排除。</p>","k":"考点5 认识的过程（两次飞跃）","kid":"166","r":141053,"tot":199283},{"i":"66935","t":"单选","q":"有中国“量子之父”之称的中科院院士潘建伟入选英国《自然》杂志“全球十大科学人物”。依托量子卫星和地面量子通信网络，潘建伟团队成功实现了北京和维也纳之间的世界首次洲际量子通信，从而使量子洲际通信技术完成了从理论到实践的飞跃这说明（  ）。","o":{"A":"A.从理论到实践的飞跃是认识过程中更为重要的一次飞跃","B":"B.从直接经验到间接经验的转化是重要的认识辩证过程","C":"C.认识世界的最终目的是追求真理","D":"D.经过人类实践检验过的认识就是真理"},"a":"A","j":"<p>量子洲际通信技术完成了从理论到实践的飞跃，体现的是认识的第二次飞跃，也是更为重要的一次飞跃，因为实践是认识的目的。因此，<span style=\"background-color: #bfedd2;\"><strong>正确答案是A</strong></span>。</p>\n<p>干扰项辨识：</p>\n<p><strong>选项 B</strong>，表述错误，直接经验与间接经验不能&ldquo;转化&rdquo;，只能结合。</p>\n<p><strong>选项C</strong>，表述错误，认识世界的最终目的是改造世界。</p>\n<p><strong>选项D</strong>，表述错误，经过实践检验过的认识有正确和错误之分，只有被实践证明是正确的认识才是人们对于客观事物及其规律的正确反映，即真理。因此，排除。</p>","k":"考点5 认识的过程（两次飞跃）","kid":"166","r":147805,"tot":194920},{"i":"66937","t":"单选","q":"近年来，互联网上经常出现一些针对特定演出、摄影作品好坏美丑的热议，网友们甚至还创造出“艺术可以冷门，但不可以邪门”的调侃。价值评价是主体对客体价值以及价值大小所作的评判或判断，通过揭示客体对于主体的意义，形成对客体的不同态度。以下关于价值评价的说法正确的是（  ）。","o":{"A":"A.价值评价以客体的属性、关系和发展过程为反映内容","B":"B.价值评价是对客观价值关系的主观反映，评价的差异性是无法避免的","C":"C.评价作为一种价值判断活动具有主观性，评价结果没有正确与错误之分","D":"D.价值评价追求客体“应该怎样”，以求“真”为认识目的"},"a":"B","j":"<p>价值评价以主客体的价值关系为反映内容，主体的意象、愿望和要求包含在其中，追求&ldquo;应该怎样&rdquo;，以求&ldquo;善&rdquo;和&ldquo;美&rdquo;为认识目的。价值评价结果与评价主体直接相关，由于评价主体存在差异或者矛盾，因而必然会使同一事物的价值评价存在差异性。价值评价虽然具有主观性，但并不是一种主观随意的认识活动，只有正确反映价值关系的评价才是正确的评价。因此，<strong><span style=\"background-color: #bfedd2;\">正确答案是B</span></strong>。</p>\n<p>干扰项辨识：</p>\n<p><strong>选项A</strong>，表述错误，价值评价属于评价性认识，知识性认识才是以客体的属性、关系和发展过程为反映内容的。</p>\n<p><strong>选项C</strong>，表述错误，价值评价的结果有正确和错误之分。</p>\n<p><strong>选项D</strong>，表述错误，价值评价以求&ldquo;善&rdquo;和&ldquo;美&rdquo;为认识目的。因此，排除。</p>","k":"考点12 真理与价值的辩证统一","kid":"177","r":127082,"tot":191034},{"i":"66938","t":"单选","q":"恩格斯指出：“自由不在于幻想中摆脱自然规律而独立，而在于认识这些规律,从而能够有计划地使自然规律为一定的目的服务。”这说明（  ）。","o":{"A":"A.必然是一种“不自由”，是不可被认识的","B":"B.自由不是“由自”，而是对必然的认识和对世界的改造","C":"C.人们可以通过认识和改造规律为人们服务","D":"D.只有摆脱必然的制约，才能争取真正的自由"},"a":"B","j":"<p>哲学上的自由是标示人的活动状态的范畴，指的是人在活动中通过认识和利用必然所表现出的一种自觉自主的状态。必然性即规律性，指的是不依赖于人的意识而存在的自然和社会发展所固有的客观规律。自由是对必然的认识和对客观世界的改造。认识必然，争取自由，是人类认识世界和改造世界的根本目标。因此，<strong><span style=\"background-color: #bfedd2;\">正确答案是B</span></strong>。</p>\n<p>干扰项辨识：</p>\n<p><strong>选项A</strong>，表述错误，必然是指规律性，是可以被认识的。</p>\n<p><strong>选项 C</strong>，表述错误，客观规律不可以改造。</p>\n<p><strong>选项D</strong>，表述错误，争取自由不是要摆脱必然的制约，而是要在遵循客观规律基础上的自由。因此，排除。多项选择题：</p>","k":"考点15 从必然走向自由","kid":"180","r":152923,"tot":185433},{"i":"66939","t":"单选","q":"在《关于费尔巴哈的提纲》这个包含新世界观天才萌芽的第一个文件中，马克思系统论述了实 践的观点，揭示了科学实践观的基本内容。科学实践观从主观和客观、主体和客体的统一中把 握实践，揭示了实践的本质，指明了实践是","o":{"A":"A.人类能动地改造世界的社会性的物质活动","B":"B.理性先天的道德活动","C":"C.主体自我实现的精神活动","D":"D.生物适应环境的活动"},"a":"A","j":"<p>科学实践观从主观和客观、主体和客体的统一中把握实践，揭示了实践的本质，指明了实践是人类能动地改造世界的社会性的物质活动，科学阐明了人类实践活动的特点、结构、形式和实践标准等问题，深刻揭示出实践与认识的发展规律，形成了完整科学的理论体系。应选A 项。</p>\n<p>干扰项辨识：康德把实践看成是理性先天的道德活动；黑格尔把实践理解为主体自我实现的精神活动，尽管他触摸到了劳动的意义，认为劳动陶冶事物，但最终还是把实践限定在抽象的精神活动范围之内；费尔巴哈把实践与物质性的活动联系起来，但他所理解的实践仅限于日常生活活动，并将实践等同于生物适应环境的活动。总之，他们都没有真正理解人类实践的本质，没有看到实践在社会生活和认识活动中的决定意义。故 <strong>B、C、D三项</strong>有误。</p>","k":"考点1 实践的本质和基本特征","kid":"71","r":177547,"tot":181128},{"i":"66940","t":"单选","q":"生于南美洲茂密森林中的西红柿曾被称为“狼桃”。16世纪，英国人佛罗达拉里公爵在旅行期 间发现了它，并带回几株种在英国皇家花园里，供皇家贵族观赏。到了18世纪，法国有一位画 家决心以身试“柿”,看其是否有毒。有记载说，这位勇敢的画家在吃西红柿之前穿戴整齐，吃 完之后就躺在床上等着上帝的“召见”。结果，他不但没有死去，也没有任何不适。于是人们才 知道西红柿原来是可以吃的。这表明","o":{"A":"A.实践是认识发展的动力","B":"B.实践是认识的来源","C":"C.实践是检验认识的标准","D":"D.实践是认识的目的和归宿"},"a":"B","j":"<p>实践观点是马克思主义认识论的首要的基本的观点，为了正确理解认识的基础和来源，必须首先考察人类的实践活动。只有通过实践，通过主客体相互作用，才能形成正确的认识。题目中，画家以身试&ldquo;柿&rdquo;是一种实践活动，实践的结果获得了\"西红柿原来是可以吃的&rdquo;这一认识，这表明实践是认识的来源。因此，本题的正确答案是 B 项。</p>\n<p>干扰项辨识：题干材料探讨的是认识的来源问题，<strong>A、D 两项</strong>均不符合题意。实践是检验认识是否是真理的唯一标准，故 <strong>C项</strong>表述不准确。</p>","k":"考点3 实践对认识的决定作用","kid":"73","r":102312,"tot":189099},{"i":"66941","t":"单选","q":"科幻基于我们今天的生活和科技想象人类未来。科幻影视改编要将观众熟悉的、认可的、可辨 识的科学元素融入创作，向观众提供一条可以进入作品的路径。“科影融合”正是铺就这条道 路的必备条件。未来世界是什么样子?真实的科学成果可以帮助我们合理地想象、推导，为科 幻影视创作提供“巨人的肩膀”。简言之，科影融合就是将科学理念、前沿知识和科技成果应用 在科幻影视作品中，使科幻想象拥有坚实的科学基础和科技支撑，增强艺术魅力。这在认识论 上启示我们","o":{"A":"A.非理性因素对于人的认识能力和认识活动具有决定作用","B":"B.感觉和幻想是认识过程的两个不同阶段","C":"C.人的认识是主观想象的结果","D":"D.认识的本质是主体在实践基础上对客体的能动反映"},"a":"D","j":"<p>科幻基于我们今天的生活和科技想象人类未来，导演、编剧将科学理念、前沿知识和科技成果应用在科幻影视作品中，体现了认识的本质是主体在实践基础上对客体的能动反映，故应选D 项。</p>\n<p>干扰项辨识：</p>\n<p><strong>A 项</strong>表述错误，非理性因素对于人的认识能力和认识活动具有激活、驱动作用，而不是决定作用。</p>\n<p><strong>B 项</strong>表述错误，感性认识和理性认识是人对客观世界的两种不同水平的反映形式，狭义上讲，是认识过程的两个不同阶段。</p>\n<p>将人的认识看成是主观自生的，是唯心主义认识论，故<strong>C 项</strong>也是错误的。</p>","k":"考点4 认识的本质","kid":"163","r":170572,"tot":177899},{"i":"66943","t":"单选","q":"习近平同志指出：“坚持和发展中国特色社会主义，全面深化改革，有效应对前进道路上可以预见和难以预见的各种困难与风险，都会提出新的课题，迫切需要我们从理论上作出新的科学回答。我们要及时总结党领导人民创造的新鲜经验，不断开辟马克思主义中国化新境界，让当代中国马克思主义放射出更加灿烂的真理光芒。”与这句话意思相近的是","o":{"A":"A.社会上一旦有技术上的需要，则这种需要会比十所大学更能把科学推向前进","B":"B.人的思维是否具有客观的真理性，这不是一个理论的问题，而是一个实践的问题。人应该在实践中证明自己思维的真理性，即自己思维的现实性和力量，自己思维的此岸性","C":"C.没有革命的理论，就没有革命的运动","D":"D.对于同一句格言，出自饱经风霜的老年人之口与出自缺乏阅历的青少年之口，其内涵是不同的"},"a":"A","j":"<p>题干引言强调实践的发展不断地提出认识的新研究课题，这种需要推动着认识向前发展。恩格斯说：&ldquo;社会一旦有技术上的需要，这种需要就会比十所大学更能把科学推向前进。&rdquo;体现的正是这个道理，充分说明实践提出认识的需要，这种需要会极大推动认识的发展。故应选 A 项。</p>\n<p>干扰项辨识：</p>\n<p><strong>B 项</strong>强调实践是检验真理的唯一标准，</p>\n<p><strong>C 项</strong>强调认识对实践的指导作用，</p>\n<p><strong>D 项</strong>强调理性认识不仅以感性认识为基础，而且要通过感性的认识来说明，故 B、C、D均不符合题意。</p>","k":"考点3 实践对认识的决定作用","kid":"73","r":39498,"tot":190288},{"i":"66945","t":"单选","q":"在树木的横断面上，常常会见到许多深浅相间的同心圆环，这就是年轮。年轮，是树木形成层 细胞进行有规律的生长和变化而形成的。许多人可能认为，树木的年轮， 一圈就代表一年。但  其实树木的年轮并不是每年都有，有时不会产生，有时一年会形成多轮，又称作“伪轮”。通过  数年轮的方法，可以大致判断树木的年龄，但要精确定年，还需要借助专业的“交叉定年”方法， 即通过大量生活在相似环境、有共同生长时期的年轮样品间的相互交叉验证，才能确定“缺轮” 和“伪轮”。“交叉定年”方法不仅能帮助精确定年，还能通过比对年轮的特征，将活树、死树与  古木样品产生的年轮序列进行交叉验证与时间“拼接”。通过这种方法，国际上已“拼接”了超  过一万年的树木年轮记录。这说明了","o":{"A":"A.认识主体在各方面的差异会导致真理是多元的","B":"B.通过逻辑推测可以检验认识是否是真理","C":"C.任何具体的认识主体总是具有自身的局限性","D":"D.得到不同认识主体认同的知识才具有真理性"},"a":"C","j":"<p>人类追求真理的过程并不是一帆风顺的，认识受到各种条件的限制。从认识的主体看，人们对客观事物的认识总要受到具体的实践水平的限制，总要受到不同的立场、观点、方法、知识水平、思维能力、生理素质等条件的限制。因此，任何具体的认识主体总是具有自身的局限性，过去人们用年轮判断树木的年龄的方法有偏差，故 C 项符合题意。尽管认识主体在立场观点方法等方面的差异会导致人们对于同一客体的认识结果有所不同，有时甚至截然相反，但这并不表明多样的观点都是真理。</p>\n<p>干扰项辨识：</p>\n<p>认识是多元的，但真理是一元的，故 <strong>A 项</strong>错误。</p>\n<p>实践是检验真理的唯一标准，逻辑推测不是检验真理的重要标准，故 <strong>B 项</strong>错误。</p>\n<p>真理具有客观性，人的认识都是对客观对象的反映，其中与客观现象相符合的认识就是真理，而非得到不同认识主体认同的知识才具有真理性，故<strong>D 项</strong>错误。</p>","k":"考点4 认识的本质","kid":"163","r":110347,"tot":176545},{"i":"66946","t":"单选","q":"认识的发展过程，首先是由实践到认识，即从实践中产生感性认识，然后能动地发展到理性认 识。这是认识过程中的第一次飞跃。感性认识和理性认识的区别是","o":{"A":"A.感性认识是可靠的，理性认识是不可靠的","B":"B.感性认识来源于实践，理性认识来源于书本","C":"C.感性认识是对现象的认识，理性认识是对本质的认识","D":"D.感性认识来源于直接经验，理性认识来源于间接经验"},"a":"C","j":"<p>感性认识是认识的低级阶段，是人在实践中通过感官对事物外部形态的直接的、具体的反映，它包括感觉、知觉、表象三种形式。感性认识的特点是直接性和具体性。这既是它的优点，也是它的缺点；既是它的可靠性所在，也是它的局限性所在。感性认识的局限性是只反映了事物的现象、各个片面和外部联系。而认识的任务却要求把握事物的本质、全体和内部联系，这是认识过程中首先遇到的一个矛盾。要解决这个矛盾，必须实现由感性认识向理性认识的飞跃。理性认识是认识的高级阶段，是人通过思维对事物内部联系的间接的、概括的反映。它包括概念、判断、推理，以及假说和理论等形式。理性认识的特点是它的间接性和抽象性。理性认识在形式上超越了客观事物，而在内容上则更深刻、更正确、更完整地反映了客观事物。故应选C 项。</p>","k":"考点5 认识的过程（两次飞跃）","kid":"166","r":154700,"tot":170989},{"i":"66947","t":"单选","q":"习近平同志常引用我国经典名句表达自己的思想，所引名句蕴含哲理，发人深思。这不仅丰富 了表达方式，也为传承优秀传统文化树立起典范。下列对习近平引用过的名句所包含哲理揭  示正确的是","o":{"A":"A.明者因时而变，知者随事而制     认识是主体对客体的直接反映","B":"B.宰相必起于州部，猛将必发于卒伍——直接经验比间接经验更可靠","C":"C.临渊羡鱼，不如退而结网——要重视实践，求真务实","D":"D.堤溃蚁孔，气泄针芒——要重视事物的质变，把握机遇促进飞跃"},"a":"C","j":"<p>临渊羡鱼，不如退而结网，这启示我们重视实践，求真务实，C 项对应正确。</p>\n<p>干扰项辨识：</p>\n<p>本题习近平用典中，明者因时而变，知者随事而制，体现的是坚持与时俱进，不断创新，同时<strong>A 项</strong>对应的哲理表述也不正确，认识是主体对客体的能动创造性反映，而不是直接反映。</p>\n<p><strong>B 项</strong>用典意为要脚踏实地，在社会实践中锻炼成长，不是强调直接经验与间接经验谁更可靠的问题，故对应错误。</p>\n<p><strong>D 项</strong>用典意为事物的发展都是从量变开始的，要重视量的积累，不是强调要重视 事物的质变，把握机遇促进飞跃，故对应不正确。</p>","k":"考点4 认识的本质","kid":"163","r":134930,"tot":171315},{"i":"66948","t":"单选","q":"马克思主义认识论即辩证唯物主义认识论与唯心主义认识论和旧唯物主义认识论的根本区别是","o":{"A":"A.把认识看作一个不断发展的过程","B":"B.坚持认识是主体对客体的反映","C":"C.坚持以科学的社会实践为特征的实践观","D":"D.人的知识来源于对“理念”的认识和回忆"},"a":"C","j":"<p>辩证唯物主义认识论是建立在实践基础上的能动的反映论。它继承了旧唯物主义的合理前提，即认识是主体对客体的反映，同时又克服其离开实践、离开辩证法考察认识问题的缺陷，坚持以科学的社会实践为特征的实践观，即实践是人类能动地改造世界的社会性的物质活动。这是马克思主义认识论即辩证唯物主义认识论与唯心主义认识论和旧唯物主义认识论的根本区别。故应选C 项。</p>\n<p>干扰项辨识：</p>\n<p><strong>A 项</strong>把认识看作一个不断发展的过程是辩证唯物主义认识论与旧唯物主义认识论的根本区别，</p>\n<p><strong>B 项</strong>坚持认识是主体对客体的反映，是辩证唯物主义认识论与唯心主义认识论的根本区别，</p>\n<p><strong>D 项</strong>非马克思主义认识论的观点。</p>","k":"考点8 实践和认识是具体的历史的统一","kid":"169","r":127748,"tot":171510},{"i":"66949","t":"单选","q":"不少老年人因为不会上网、不会使用智能手机，无法享受智能化服务带来的便利。2020年11 月印发的《关于切实解决老年人运用智能技术困难的实施方案》提出，在各类日常生活场景 中，必须保留老年人熟悉的传统服务方式，充分保障在运用智能技术方面遇到困难的老年人 的基本需求。这表明","o":{"A":"A.真理必须以价值尺度为前提","B":"B.主客体之间的价值关系是一种自然的现成关系","C":"C.评价结果的正确与否依赖于对客体状况和主体需要的认识","D":"D.同一客体相对于主体的不同需要会产生不同的价值"},"a":"C","j":"<p>C项评价结果的正确与否依赖于对客体状况和主体需要的认识符合题意，评价是关于主客体之间价值关系的认识，是对客体对于主体需要的意义的判断。人们是否正确地做出这种判断，取决于人对客体和主体的双重认识，这种认识不仅包括对客体属性和规律的认识，也包括对主体的规定性和需要的认识。因此，要让老人享受智能化服务带来的便利，必须保留老年人熟悉的传统服务方式，就要充分保障在运用智能技术方面遇到困难的老年人的基本需求。</p>\n<p>干扰项辨识：</p>\n<p><strong>A 项</strong>表述错误，价值必须以真理尺度为前提。</p>\n<p><strong>B 项</strong>表述错误，价值关系的形成依赖于主体的创造，使客体潜在的价值转化为现实的存在。因此，主客体之间的价值关系不是一种自然的 现成关系，而是主体在实践基础上确立的同客体之间的一种创造性的关系。</p>\n<p><strong>D 项</strong>表述正确，但 不符合题干表达的意思。老年人与青年人都需要科技助力生活，并非科技对老年人没有价值。</p>","k":"考点12 真理与价值的辩证统一","kid":"177","r":64935,"tot":179282},{"i":"66950","t":"单选","q":"康德主张知识的形式是头脑里固有的，孟子认为有“不学而能”的“良能”和“不虑而知”的“良 知”,柏拉图认为认识是对神秘理念的回忆。上述观点属于","o":{"A":"A.不可知论的观点","B":"B.辩证唯物主义认识论的观点","C":"C.唯心主义认识论的观点","D":"D.机械唯物主义认识论的观点"},"a":"C","j":"<p>同唯物主义认识论相对立的唯心主义认识论把人的认识看作是先于客观物质世界、先于社会实践、先于感性经验，人脑先天固有的或上帝所赐予的东西。唯心主义认识论坚持从感觉和思想到物的认识路线，否认认识对象的客观实在性，否认认识是对客观物质世界的反映，否认实践是认识的基础，把认识看作是对精神自身的认识。主观唯心主义认为，认识是人脑先天固有的，主观自生的，如题目中康德和孟子的观点。客观唯心主义认为，认识是来自&ldquo;神的启示&rdquo;或&ldquo;绝对观念&rdquo;,如题目中柏拉图观点。因此，本题应选C 项。</p>","k":"考点4 认识的本质","kid":"163","r":128970,"tot":167602},{"i":"66951","t":"单选","q":"毛泽东强调：“一个正确的认识，往往需要经过由物质到精神，由精神到物质，即由实践到认 识，由认识到实践这样多次的反复，才能够完成。”如此“实践、认识、再实践、再认识，循环往复 以至无穷，而实践和认识之每一循环的内容，都比较地进到了高一级的程度”。这就是认识运动的总规律，这表明认识是","o":{"A":"A.一个量变到质变不断积累的过程","B":"B.一个封闭式的循环过程","C":"C.一个直线式的发展过程","D":"D.一个波浪式前进和螺旋式上升的过程"},"a":"D","j":"<p>\"实践、认识、再实践、再认识，循环往复以至无穷，而实践和认识之每一循环的内容，都比较地进到了高一级的程度&rdquo;。这就是认识辩证运动发展的基本过程，也是认识运动的总规律，表明认识是一个反复循环和无限发展的过程。这个过程既是认识在实践基础上沿着科学性方向不断深化发展的过程，也是实践在认识的指导下沿着合理性方向不断深入推进的过程。这个过程既不是封闭式的循环，也不是直线式的发展，往往充满了曲折以至反复， 因而是一个波浪式前进和螺旋式上升的过程。故应选D 项。</p>","k":"考点5 认识的过程（两次飞跃）","kid":"166","r":148682,"tot":164176},{"i":"66953","t":"单选","q":"改革开放是前无古人的崭新事业。习近平同志在阐述改革开放的方法论时强调：“摸着石头 过河和加强顶层设计是辩证统一的。”这一论断的哲学依据是","o":{"A":"A.感性认识与理性认识的辩证统一","B":"B.实践与理论的辩证统一","C":"C.抽象与具体的辩证统一","D":"D.分析与综合的辩证统一"},"a":"B","j":"<p>摸着石头过河和加强顶层设计之间辩证统一的关系，要求我们在改革开放中将实践与理论有机统一起来，使其互促互进。在摸着石头过河，大胆试验、大胆突破时，心中要装着全局，以顶层设计的相关理念来引领实践探索，努力为顶层设计提供实践经验；在加强顶层设计时，不能脱离实践探索所积累的经验，使顶层设计更加符合我国国情和实践需要。故应选B项。</p>","k":"","kid":"","r":142294,"tot":164435},{"i":"66956","t":"单选","q":"马克思指出：“自由王国只是在必要性和外在目的规定要做的劳动终止的地方才开始；因而按 照事物的本性来说，它存在于真正物质生产领域的彼岸。”“在这个必然王国的彼岸，作为目的  本身的人类能力的发挥，真正的自由王国，就开始了。但是，这个自由王国只有建立在必然王国的基础上，才能繁荣起来。”这说明","o":{"A":"A.从自由王国到必然王国是永无止境的无限发展过程","B":"B.认识世界和改造世界、改造客观世界和改造主观世界的过程，在达到自由王国便终止了","C":"C.自由是对必然的认识和对客观世界的改造","D":"D.必然王国和自由王国本质上是人类在客观世界面前所处的同一种社会活动状态"},"a":"C","j":"<p>马克思这段话告诉我们认识世界和改造世界、改造客观世界和改造主观世界的过程，也就是从必然王国走向自由王国的过程。自由是对必然的认识和对客观世界的改造。认识必然，争取自由，是人类认识世界和改造世界的根本目标，是一个世界历史性的过程。由必然到自由表现为人类不断地从必然王国走向自由王国的过程。必然王国和自由王国是人类在客观世界面前所处的两种不同的社会活动状态。从必然王国到自由王国是永无止境的无限发展过程。由此可见<strong>A、B、D三项</strong>均表述错误，应选C 项。</p>","k":"考点15 从必然走向自由","kid":"180","r":100330,"tot":166878},{"i":"66964","t":"单选","q":"“芳林新叶催陈叶，流水前波让后波”体现了新旧事物之间的辩证关系。区分新旧事物是理解辩证法的关键，二者的区别在于","o":{"A":"A.出现时间的先后","B":"B.形式的新旧","C":"C.力量大小的对比","D":"D.是否符合客观规律和发展的必然趋势"},"a":"D","j":"<p>本题考查新旧事物的区别。唯物辩证法认为，<span style=\"color: #e03e2d;\">新事物是指符合客观发展规律、具有强大生命力和远大发展前途的东西；旧事物是指那些同客观规律背道而驰、丧失历史必然性、日趋灭亡的东西。区分新旧事物的根本标准，是看它是否符合客观规律，有没有强大的生命力和远大的发展前途</span>。因此，<strong>选项D正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，只能说&ldquo;新事物往往产生于旧事物之后&rdquo;，但这不是绝对的，不能把产生时间的先后作为判断新旧事物的标准。故不选。</p>\n<p><strong>选项B</strong>，一般情况下，事物的内容和形式是一致的，但也有相对脱离的情况，在现实生活中，我们经常看到旧事物为了证明自己的&ldquo;新&rdquo;而采取新的形式，所以，不能以形式的新引旧作为判断新旧事物的标准。故不选。</p>\n<p><strong>选项C</strong>，新事物在开始时力量一般都是比较弱小的，处于被支配的地位，而与其对立的旧事物则还保持着较为强大的力量，处于支配的地位。所以，不能以力量的大小作为判断新旧事物的标准。故不选。</p>","k":"考点1 唯物辩证法两大总特征","kid":"68","r":157755,"tot":159743},{"i":"66967","t":"单选","q":"“凡事预则立，不预则废”在哲学上反映的是","o":{"A":"A.可能和现实的辩证关系","B":"B.原因和结果的辩证关系","C":"C.现象和本质的辩证关系","D":"D.必然和偶然的辩证关系"},"a":"B","j":"<p>本题考查因果联系。唯物辩证法认为任何现象都会引起其他现象的产生，任何现象的产生都是由其他现象所引起的。这种引起和被引起的关系，叫作因果联系。由于一定的原因必然引起一定的结果，这就要求人们应当根据某种原因，预见事物发展的结果。<span style=\"color: #e03e2d;\">本题题干中的&ldquo;预&rdquo;和&ldquo;不预&rdquo;就是原因，&ldquo;立&rdquo;和&ldquo;废&rdquo;就是由它们引起的结果。&ldquo;凡事预则立&rdquo;告诉我们，有了对后果的科学预见，才能正确指导自己的具体行动，促使事物向人们所期望的方向发展。&ldquo;不预则废&rdquo;告诉我们，如果只顾眼前的利益，不顾长远的结果，必然会给工作和日常生活带来危害</span>。因此，<strong>选项B正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，可能和现实是对立统一的关系。但本题题干主要强调的是因果联系，并没有涉及可能和现实的关系，故不选。</p>\n<p><strong>选项C</strong>，现象和本质是既对立又统一的，二者是相互依存、相互包含、相互转化的。但本题题干并没有涉及现象和本质的关系，故不选。</p>\n<p><strong>选项D</strong>，必然与偶然是辩证统一的，偶然中隐藏着必然，而任何偶然又总是服从于必然，二者在一定条件下可以相互转化。但本题题干并没有涉及必然和偶然的关系，故不选。</p>","k":"考点7 原因和结果（唯物辩证法第三对基本范畴）","kid":"150","r":91940,"tot":166600},{"i":"66970","t":"单选","q":"虎求百兽而食之，得狐。狐曰：“子无敢食我也。天帝使我长百兽，今子食我，是逆天帝命也。子以我为不信，吾为子先行，子随我后，观百兽之见我而敢不走乎！”虎以为然，故遂与之行。兽见之皆走。虎不知兽畏己而走也，以为畏狐也。虎之所以犯这种错误，是因为其割裂了","o":{"A":"A.必然与偶然之间的关系","B":"B.内容与形式之间的关系","C":"C.本质与现象之间的关系","D":"D.可能与现实之间的关系"},"a":"C","j":"<p>本题考查现象和本质的关系。通过&ldquo;狐假虎威&rdquo;这则寓言故事，我们可以认识到，<span style=\"color: #e03e2d;\">百兽害怕老虎是事物的本质，而害怕狐狸只是本质的一种表现，即现象，并且这是一种假象</span>。因此，<strong>选项C正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，不能说百兽害怕老虎是必然的，而害怕狐狸是偶然的，它们之间不是必然与偶然的关系。故不选。</p>\n<p><strong>选项B</strong>，内容是构成事物的基本要素的总和，而形式是要素结合的结构和表现方式，并不能说害怕狐狸是害怕老虎的形式，因为&ldquo;害怕狐狸&rdquo;本身就是一个假命题，它是一种假象，而不是某种形式。故不选。</p>\n<p><strong>选项D</strong>，不管是百兽害怕老虎的&ldquo;本质&rdquo;，还是害怕狐狸的&ldquo;假象&rdquo;，这些都是客观存在的，并不是某种可能，因此，&ldquo;狐假虎威&rdquo;的故事表达的不是&ldquo;可能与现实&rdquo;之间的辩证关系。说法错误，故不选。</p>","k":"考点6 现象和本质（唯物辩证法第二对基本范畴）","kid":"148","r":139017,"tot":160515},{"i":"66972","t":"单选","q":"一根筷子放入盛满清水的杯中，看上去像被折断了一样。关于这一现象，下列说法正确的是","o":{"A":"A.通过感官感知到的都是对客观事物真实的反映","B":"B.人们看到筷子像被折断了一样完全是一种主观的错觉","C":"C.筷子的本质无法通过现象表现出来","D":"D.这是一种用歪曲形式表现本质的现象"},"a":"D","j":"<p>本题考查现象和本质的关系。<span style=\"color: #e03e2d;\">&ldquo;一根筷子放入盛满清水的杯中，看上去像被折断了一样。&rdquo;这是一种用歪曲形式表现本质的现象，即假象，&ldquo;看上去像被折断了一样&rdquo;的假象歪曲了&ldquo;筷子本身并没有断&rdquo;这一本质。</span>因此，<strong>选项D正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，如果通过感官感知到的都是对事物正确的、真实的反映的话，那么理性思维就显得没有必要了。因此，这种观点是错误的，事物的本质往往会隐藏起来，或者通过一些现象（包括假象）表现出来，故不选。</p>\n<p><strong>选项B</strong>，错觉是一种主观的错误感知，而本题所描述的&ldquo;筷子被折断了&rdquo;并不是主观的，因为通过光的折射，人们看到的的确是&ldquo;折断了的筷子&rdquo;，这是客观存在的。说法错误，故不选。</p>\n<p><strong>选项C</strong>，没有不表现为现象的本质，也没有不表现本质的现象。因此，筷子的本质是一定可以通过现象表现出来的，无论是真象还是假象。说法错误，故不选。</p>","k":"考点6 现象和本质（唯物辩证法第二对基本范畴）","kid":"148","r":82448,"tot":166014},{"i":"66973","t":"单选","q":"对立统一规律之所以是唯物辩证法的实质和核心，是因为它揭示了","o":{"A":"A.事物发展的形式和状态","B":"B.事物发展的方向和道路","C":"C.事物发展的内在动力","D":"D.事物的内在要素及结构形式"},"a":"C","j":"<p>本题考查对立统一规律。<span style=\"color: #e03e2d;\">对立统一规律之所以是唯物辩证法的实质和核心，是因为对立统一规律揭示了事物普遍联系的根本内容和永恒发展的内在动力，从根本上回答了事物为什么会发展的问题。</span>对立统一规律是贯穿量变质变规律、否定之否定规律以及唯物辩证法基本范畴的中心线索，也是理解这些规律和范畴的&ldquo;钥匙&rdquo;。因此，<strong>选项C正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，量变质变规律揭示了事物发展的形式和状态，体现了事物发展的渐进性与飞跃性的统一。故不选。</p>\n<p><strong>选项B</strong>，否定之否定规律揭示了事物发展的方向和道路。故不选。</p>\n<p><strong>选项D</strong>，内容和形式是揭示事物内在要素同这些要素的结构和表现方式的关系范畴。故不选。</p>","k":"考点2 对立统一规律（唯物辩证法第一规律）","kid":"69","r":102485,"tot":163613},{"i":"66975","t":"单选","q":"中医在实践中逐渐形成了一种“取类比象”的思维方法：“取类”，把长期实践中积累的经验集中起来，发现事物之间的相类性，“观其所聚，而天地万物之情可见矣”；“比象”，在对“类”有了认识之后，“引而伸之，触类而长之”。中医“取类比象”的思维方法说明","o":{"A":"A.抓住主要矛盾即可获得实践的成功","B":"B.矛盾同一性与斗争性无法共存","C":"C.矛盾的普遍性与矛盾的特殊性是相互联结的","D":"D.从整体着眼可以把握事物部分的性质"},"a":"C","j":"<p>本题考查矛盾的普遍性和特殊性的关系。<span style=\"color: #e03e2d;\">矛盾的普遍性是指矛盾存在于一切事物中，存在于一切事物发展过程的始终，即所谓矛盾无处不在，无时不有。矛盾的特殊性是指各个具体事物的矛盾及每一矛盾的各个方面在发展的不同阶段各有其特点</span>。矛盾的普遍性即矛盾的共性，矛盾的特殊性即矛盾的个性。矛盾的共性和个性相统一的关系，既是客观事物固有的辩证法，也是科学的认识方法。人的认识的一般规律就是由个别上升到一般，再由一般到个别的辩证发展过程。中医中&ldquo;取类&rdquo;是为了发现事物之间的&ldquo;普遍性&rdquo;，&ldquo;比象&rdquo;则是为了解决&ldquo;特殊性&rdquo;问题。因此，<strong>选项C正确。</strong></p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，虽然主要矛盾在矛盾体系中处于支配地位，对事物发展起决定作用，但并不是说抓住了主要矛盾就可以获得实践的成功。故不选。</p>\n<p><strong>选项B</strong>，同一性和斗争性是矛盾的两种基本属性，是矛盾双方相互联系的两个方面。矛盾的同一性和斗争性是相互联结、相互制约的。与题干无关，故不选。</p>\n<p><strong>选项D</strong>，从内部根本矛盾出发才能把握事物的性质，与整体没有直接关系。故不选。</p>","k":"考点2 对立统一规律（唯物辩证法第一规律）","kid":"69","r":139270,"tot":158289},{"i":"66977","t":"单选","q":"鲁迅在评《三国演义》时说：“至于写人，亦颇有失，以致欲显刘备之长厚而似伪，状诸葛之多智而近妖。”这一评述所蕴含的哲理是","o":{"A":"A.要区分事物的两重性","B":"B.要把握事物的度","C":"C.对事物既要肯定，又要否定","D":"D.要把事物看作一个整体"},"a":"B","j":"<p>本题考查适度原则。度是保持事物质的稳定性的限度、幅度、范围等具体界限，是质和量的统一。事物的变化是否超出了度是量变与质变相互区别的根本标志。<span style=\"color: #e03e2d;\">鲁迅认为《三国演义》中的人物描写存在一定的不足，即有点&ldquo;过&rdquo;。本来想尽量呈现刘备的忠厚，但较&ldquo;过&rdquo;的描写使刘备倒显得有些虚伪。同样，本来想呈现诸葛亮的足智多谋，结果写得有点超脱人类而&ldquo;近妖&rdquo;。其所蕴含的哲理就是要掌握适度原则，把握分寸、火候，防止&ldquo;过犹不及&rdquo;</span>。因此，<strong>选项B正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，两重性是指客观事物的对立统一。任何事物都具有两重性，要求我们既要看到事物的正面，又要看到事物的反面。本题题干并没有涉及事物的两重性，故不选。</p>\n<p><strong>选项C</strong>，坚持辩证的否定观，就要对一切事物采取科学的分析态度，要同时看到事物的肯定方面和否定方面，在肯定中看到否定，在否定中看到肯定，不能肯定一切或否定一切。本题题干并没有涉及辩证的否定观，故不选。</p>\n<p><strong>选项D</strong>，&ldquo;要把事物看作一个整体&rdquo;是联系的观点，与题干无关，故不选。</p>","k":"考点3 量变质变规律（唯物辩证法第二规律）","kid":"143","r":100536,"tot":161738},{"i":"66980","t":"单选","q":"如果把一只青蛙直接放进热水锅里，它会迅速跳出锅外；如果把一只青蛙放进冷水锅里，慢慢地加温，青蛙并不会立即跳出锅外，水温逐渐提高的最终结局是青蛙被煮死了，这是因为等水温高到青蛙无法忍受时，它已经来不及或者说没有能力跳出锅外了。这说明","o":{"A":"A.否定因素是事物发展的动力","B":"B.事物发展是量变与质变的统一","C":"C.偶然决定事物的发展方向","D":"D.联系是无条件的、主观的"},"a":"B","j":"<p>本题考查量变质变规律，属于分析理解题。<span style=\"color: #e03e2d;\">由于任何事物都是质和量的统一体，因而事物的变化表现为量变和质变两种运动状态</span>。量变是事物数量的增减和组成要素排列次序的变动，是保持事物的质的相对稳定的不显著的变化，体现了事物渐进过程的连续性。质变是事物性质的根本变化，是事物由一种质态向另一种质态的飞跃，体现了事物渐进过程和连续性的中断。区分量变和质变的根本标志是事物的变化是否超出度，在度的范围内的变化是量变，超出度的范围的变化是质变。因此，<strong>选项B正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，与题意不符且表述错误。矛盾推动事物的发展，说明事物发展的根本原因不在于事物的外部，在于事物内部的矛盾性，而不是否定因素。故不选。</p>\n<p><strong>选项C</strong>，与题意不符且表述错误。必然在事物发展中居于支配地位，决定着事物发展的方向；偶然居于从属地位，对发展的必然过程起促进或延缓作用，使发展的确定趋势带有一定的特点和偏差。故不选。</p>\n<p><strong>选项D</strong>，与题意不符且表述错误。事物的联系是事物本身所固有的，具有客观性，不是主观臆造的。世界的普遍联系是通过&ldquo;中介&rdquo;来实现的。所谓中介，就是事物相互联系的媒介、环节或桥梁。因此，联系是有条件的，故不选。</p>","k":"考点3 量变质变规律（唯物辩证法第二规律）","kid":"143","r":146063,"tot":156431},{"i":"66983","t":"单选","q":"诗歌《圆的自白》：“圆，虽然完美，却从来不知满足。因为它知道，每一个终点，都是新的起点。”这给我们的启示是","o":{"A":"A.肯定就是否定，终点就是起点","B":"B.辩证否定是事物发展的重要环节","C":"C.否定之否定阶段是向原来出发点的“回复”","D":"D.否定是绝对的否定，是不包含肯定的否定"},"a":"B","j":"<p>本题考查辩证的否定观。事物内部都存在着肯定因素和否定因素。肯定因素是维持现存事物存在的因素，否定因素是促使现存事物灭亡的因素。<span style=\"color: #e03e2d;\">否定是事物发展的环节，它是旧事物向新事物的转变，是从旧质到新质的飞跃</span>。只有经过否定，旧事物才能向新事物转变。所以每个终点都是一个新的起点。因此，<strong>选项B正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，辩证的否定观认为要对一切事物采取科学的分析态度，既要看到事物的肯定方面，又要看到事物的否定方面，在肯定中看到否定，在否定中看到肯定，不能肯定一切或否定一切。但是，肯定和否定还是具有明确界限的，不能模糊二者的界限而犯诡辩论的错误。故不选。</p>\n<p><strong>选项C</strong>，事物的辩证发展就是经过两次否定、三个阶段，形成一个周期，其中否定之否定阶段仿佛是向原来出发点的&ldquo;回复&rdquo;，但这是在更高阶段上的&ldquo;回复&rdquo;。选项C将其简单表述为&ldquo;向原来出发点的&lsquo;回复&rsquo;&rdquo;，说法错误，故不选。</p>\n<p><strong>选项D</strong>，&ldquo;否定是绝对的否定，是不包含肯定的否定&rdquo;是一种典型的形而上学否定观。辩证的否定观认为，要在肯定中看到否定，在否定中看到肯定。故不选。</p>","k":"考点4 否定之否定规律（唯物辩证法第三规律）","kid":"145","r":90213,"tot":163451},{"i":"66986","t":"单选","q":"恩格斯说：“实际上，蔑视辩证法是不能不受惩罚的。对一切理论思维尽可以表示那么多的轻视，可是没有理论思维，的确无法使自然界中的两件事联系起来或者洞察二者之间的既有的联系。”这说明","o":{"A":"A.规律是事物运动发展中的本质的、必然的、稳定的联系","B":"B.人们在客观规律面前是消极被动、无所作为的","C":"C.正确的理论思维能使人们增强驾驭规律的能力","D":"D.客观性是规律的根本特性"},"a":"C","j":"<p>本题考查唯物辩证法。<span style=\"color: #e03e2d;\">题干中的&ldquo;可是没有理论思维，的确无法使自然界中的两件事联系起来或者洞察二者之间的既有的联系&rdquo;，表明理论思维是十分重要的，能够洞察事物之间的联系</span>。规律是事物运动发展中的本质的、必然的、稳定的联系，正确的理论思维能使人们增强驾驭规律的能力，错误的理论思维会走向真理的反面。因此，<strong>选项C正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，说法正确但与题意不符。题干主要强调的是理论思维，并没有涉及规律的含义。故不选。</p>\n<p><strong>选项B</strong>，人们在实践中，透过大量的外部现象，可以发现或认识客观规律，并利用这种认识指导实践，达到改造自然、改造社会、为社会谋福利的目的。所以人们在客观规律面前并不是消极被动、无所作为的。说法错误，故不选。</p>\n<p><strong>选项D</strong>，说法正确但与题意不符。题干主要强调的是理论思维，并没有涉及规律的客观性。故不选。</p>","k":"考点12 辩证思维方法","kid":"160","r":64923,"tot":164645},{"i":"66994","t":"单选","q":"实践是人们能动地改造世界的客观物质性活动，其基本类型有三种，其中最终起决定作用的是 ","o":{"A":"A.物质生产实践                         ","B":"B.社会政治实践","C":"C.处理社会关系的实践                   ","D":"D.科学文化实践"},"a":"A","j":"<p><strong>本题考查实践的基本类型。</strong>实践的基本类型包括物质生产实践、社会政治实践和科学文化实践。其中物质生产实践是人 类最基本的实践活动，是决定一切实践活动的根本前提。在实践的基本形式中，最终起决定 作用的是物质生产实践。因此，<strong>选项A 正确。</strong></p>\n<p>干扰项分析：<strong>选项 B、C、D,</strong> 社会政治实践是形成各种社会关系的实践活动(选项C), 表现为人们之间的 交往和政治活动，但不管是社会政治实践(<strong>选项 B</strong>) 还是科学文化实践(<strong>选项 D</strong>) 都不起决 定作用。</p>","k":"考点2 实践的基本结构和形式","kid":"72","r":139968,"tot":153957},{"i":"66996","t":"单选","q":"实践高于理论的认识，是因为实践具有","o":{"A":"A.普遍性          ","B":"B.绝对性            ","C":"C.客观实在性         ","D":"D.直接现实性"},"a":"D","j":"<p><strong>本题考查实践的特征。</strong>实践是人类能动地改造世界的社会性的物质活动，具有客观实在性(直接现实性是客观实在 性的具体表现)、自觉能动性和社会历史性等基本特征。辩证唯物主义认识论认为，实践之所 以高于理论的认识，是因为它具有直接现实性的特点。实践是改造世界的客观物质活动，不 是纯粹的精神活动，而是以感性事物为对象的现实的物质活动。因此，实践所具有的直接现 实性也就是实践活动的客观实在性。因此，<strong>选项 D 正确。</strong></p>\n<p>干扰项分析：</p>\n<p><strong>选项A、B</strong>, 任何实践和理论的认识，既有绝对性、普遍性，又有相对性、局限性。</p>\n<p><strong>选项C</strong> 是包含着<strong>选项 D</strong> 的，因为实践的直接现实性是它的客观实在性的具体表现。另外，题 干出自列宁的原话。列宁说：&ldquo;实践高于(理论的)认识，因为它不但有普遍性的品格，并且 还有直接现实性的品格。&rdquo;这是一道单选题，很显然，在普遍性、客观实在性和直接现实性之 间，根据递进关系可知，列宁更强调直接现实性。</p>","k":"考点1 实践的本质和基本特征","kid":"71","r":66526,"tot":163651},{"i":"66998","t":"单选","q":"承认真理内容的客观性，也就是承认","o":{"A":"A.真理的相对性                        ","B":"B.真理的绝对性","C":"C.真理标准的不确定性                  ","D":"D.真理和客观事物是同一的"},"a":"B","j":"<p><strong>本题考查真理的绝对性。</strong></p>\n<p>真理的绝对性有两方面的含义：</p>\n<p>一是指任何真理都标志着主观与客观之间的符合，都必然包 含同客观对象相符合的客观内容，都同谬误有原则的界限。否则，就不能称其为真理，这一点是绝对的、无条件的。在这个意义上，承认了客观真理，也就是承认了真理的绝对性。</p>\n<p>二是人类认识按其本性来说，能够正确认识无限发展着的物质世界，认识每前进一步，都是对无限发展着的物质世界的接近，这一点也是绝对的、无条件的。在这个意义上，承认了世界的可知性，也就是承认了真理的绝对性。因此，<strong>选项B 正确。</strong></p>\n<p>干扰项分析：</p>\n<p><strong>选项A</strong>, 真理的相对性是指真理有待于扩展和深化。</p>\n<p><strong>选项C</strong>, 真理标准的不确定性和真理的绝对性无关。选项D, 说法错误，真理是对客观事物及其规律的正确认识，和客观事物不是一回事。</p>","k":"考点9 真理及其特性","kid":"171","r":96065,"tot":159040},{"i":"67002","t":"单选","q":"未来学家尼葛洛庞蒂说：“预测未来的最好办法就是把它创造出来。”从认识与实践的关系看，这句话对我们的启示是","o":{"A":"A.认识总是滞后于实践                  ","B":"B.实践是认识的先导","C":"C.实践高于认识                        ","D":"D.实践与认识是合一的"},"a":"C","j":"<p><strong>本题考查认识的含义。</strong>列宁明确指出：&ldquo;实践高于(理论的)认识，因为它不但有普遍性的品格，并且还有直接现实 性的品格。&rdquo;所谓实践具有直接现实性，是指它作为人的客观物质活动，现实地改变着世界的 状况。所谓实践高于认识，是指实践能够检验认识的对错。因此，<strong>选项C 正确。</strong></p>\n<p>干扰项分析：</p>\n<p><strong>选项A, </strong>&ldquo;总是&rdquo;说法错误。</p>\n<p><strong>选项B,</strong> &ldquo;先导&rdquo;说法错误，实践先于认识，但不指导认识，而是认识(理论)指导实践。</p>\n<p><strong>选项D,</strong> 说法错误，实践和认识具有同一性，但同一不等于合一，类似的错误说法还有王阳明的&ldquo;知行合一&rdquo;论。</p>","k":"考点4 认识的本质","kid":"163","r":35809,"tot":168045},{"i":"67006","t":"单选","q":"辩证唯物主义认识论与唯心主义认识论、旧唯物主义认识论的根本区别在于是否承认 ","o":{"A":"A.认识客体具有客观性                  ","B":"B.认识是一个反复的过程","C":"C.物质世界可以被认识                  ","D":"D.社会实践是认识的基础"},"a":"D","j":"<p><strong>本题考查辩证唯物主义认识论与唯心主义认识论、旧唯物主义认识论的根本区别。</strong>辩证唯物主义认识论与唯心主义认识论、旧唯物主义认识论的根本区别在于是否承认社会实 践是认识的基础。</p>\n<p><strong>选项 A、D </strong>是辩证唯物主义认识论与唯心主义认识论的区别，<strong>选项B、D</strong> 是 辩证唯物主义认识论与旧唯物主义认识论的区别。</p>\n<p>另外，<strong>选项A </strong>是辩证唯物主义认识论与旧 唯物主义认识论的共同点；<strong>选项B</strong> 是辩证唯物主义认识论与唯心主义认识论的共同点。因此， <strong>选项 D 正确。</strong></p>\n<p>干扰项分析：</p>\n<p>本题较有难度，知识要点回顾如下：</p>\n<p>辩证唯物主义认识论坚持客观(<strong>选项A</strong>), 坚持实践(<strong>选 项 D</strong>), 坚持辩证(<strong>选项B</strong>)。</p>\n<p>旧唯物主义认识论坚持客观(<strong>选项A</strong>), 否认实践(<strong>选项 D</strong>), 否 认辩证(<strong>选项 B</strong>)。</p>\n<p>唯心主义认识论坚持辩证(<strong>选项B</strong>), 否认客观(<strong>选项A</strong>), 否认实践(<strong>选 项D</strong>)。 这样，选项之间的关系就一目了然了。</p>\n<p>另外，关于<strong>选项C,</strong> 在世界是否可知的问题 上，唯物主义坚持可知论，唯心主义既有可知论，也有不可知论。</p>","k":"考点8 实践和认识是具体的历史的统一","kid":"169","r":114256,"tot":154869},{"i":"67009","t":"单选","q":" “知识就是力量。”对这一命题理解正确的是","o":{"A":"A.真理和价值是统一的                  ","B":"B.知识是社会发展的根本动力","C":"C.知识精英是历史的创造者              ","D":"D.知识决定社会形态的更替"},"a":"A","j":"<p><strong>本题考查价值和真理在实践中的辩证统一。</strong></p>\n<p>真理和价值在实践基础上是辩证统一的，主要体现在以下几个方面：</p>\n<p>(1)成功的实践必然是 以真理和价值的辩证统一为前提的。任何成功的实践都必然是既遵循真理尺度，又符合价值 尺度，并将二者有机地统一起来的结果。</p>\n<p>(2)价值的形成和实现以坚持真理为前提，而真理 又必然是具有价值的。</p>\n<p>(3)真理和价值在实践和认识活动中是相互制约、相互引导、相互促 进的。题干中的&ldquo;知识&rdquo;是指真理性认识，&ldquo;力量&rdquo;是指对人的有用性，这就是真理和价值的 辩证统一。因此，<strong>选项A 正确。</strong></p>\n<p>干扰项分析：</p>\n<p><strong>选项B,</strong> 说法错误，社会发展的根本动力是社会基本矛盾。</p>\n<p><strong>选项C,</strong> 属于唯心史观的观点，人民群众是历史的创造者。</p>\n<p><strong>选项D, </strong>社会形态的更替是由社会发展的客观规律决定的。</p>","k":"考点12 真理与价值的辩证统一","kid":"177","r":110085,"tot":154705},{"i":"67012","t":"单选","q":"我国科学家经过艰苦努力，成功克隆了两只猕猴。很多人都以为，这项技术的突破并不大， 因为多年前，英国已经诞生了克隆羊。但实际上，当初的克隆羊采用的是胚胎分裂技术，而中国科学家采用的则是更为先进的体细胞克隆技术。由此可见","o":{"A":"A.真理是绝对内容和客观形式的统一","B":"B.科学技术的发展可以消除真理和谬误的界限","C":"C.人们对客观事物的认识受到客观条件的局限","D":"D.价值评价的结果是由主体的认识所决定的"},"a":"C","j":"<p><strong>本题考查认识的相关内容</strong>。题干的意思是，中国科学家的技术突破是很大的，实现了从胚胎分裂技术到体细胞克隆技术 的跃升，但有的人认为这个技术的突破并不大。为什么会出现这种情况呢?很显然，这是因 为人们对客观事物的认识受到客观条件的限制。因此，<strong>选项C 正确。</strong></p>\n<p>干扰项分析：</p>\n<p><strong>选项A, </strong>说法错误，真理是客观内容和主观形式的统一。</p>\n<p><strong>选项B, </strong>说法错误，在一定条件下，真理和谬误的界限是绝对的，科学技术再怎么发展，也 不能消除这一界限。</p>\n<p><strong>选项D, </strong>说法错误，价值评价的结果取决于主客体之间的关系，而不仅仅取决于主体的认识。</p>","k":"考点9 真理及其特性","kid":"171","r":95825,"tot":156429},{"i":"67013","t":"多选","q":"2017年6月，我国科学家利用“墨子号”量子科学实验卫星在国际上率先成功实现了千公里级的星地双向量子纠缠分发。“量子纠缠”是两个（或多个）粒子共同组成的量子状态，无论粒子之间相隔多远，测量其中一个粒子必然会影响其他粒子。“量子纠缠”现象虽然未被完全认知，但他仍然能够说明（ ） ","o":{"A":"A.物质世界联系的客观性和普遍性 ","B":"B.事物联系的主观性和偶然性 ","C":"C.事物联系的复杂性和多样性 ","D":"D.世界的真正统一性在于它的物质性 "},"a":"ACD","j":"<p>[难度系数]0.312本题考查的考点是：世界的物质统一性原理，事物普遍联系原理。联系是指事物内部各要素之间和事物之间相互影响、相互制约和相互作用的关系。题干中&ldquo;量子纠缠&rdquo;现象，无论粒子之间相隔多远，测量其中一个粒子必然会影响其他粒子，就证明了联系的客观性与普遍性，而多个粒子之间的联系虽然未被完全认识，但这些粒子归根到底也是物质，统一于物质，其所具有的联系虽然复杂，但最终也是可以被认知的。因此，正确选项是ACD。 【干扰项辨识】选项B，事物的联系具有客观性，普遍性，多样性，有条件性。不是主观性和偶然性，因此，排除。必背金句：联系的特点：①联系具有客观性。②联系具有普遍性。③联系具有多样性。④联系具有条件性。</p>","k":"考点15 世界的物质统一性原理","kid":"135","r":82888,"tot":158350},{"i":"67022","t":"多选","q":"母质、气候、生物、地形、时间是土壤形成的五大关键成土因素。母质是土壤形成物质基础的初始无机养分的最初来源。气候导致矿物的风化和合成，有机质的形成和积累，土壤中物质的迁移，分解和合成。生物包括植物、动物和微生物等，是促进土壤发生发展最活跃的因素。地形可以使物质在地表进行再分配，使土壤及母质在接受光、热、水等条件方面发生差异。时间是阐明土壤形成发展的历史动态过程，母质、气候、生物和地形等对成工过程的作用随着时间延续而加强。土壤的生产过程说明","o":{"A":"A.事物总是作为过程而存在","B":"B.时空是物质运动的存在形式","C":"C.事物的发展总是呈现出线性上升的态势","D":"D.事物的产生是多重因素相互作用的结果"},"a":"ABD","j":"<p>[难度系数]0.390本题考查的考点是：物质的根本属性和基本存在形式，发展的实质，事物发展的过程性。题干中指出在土壤的形成过程中，母质、气候、生物、地形、时间是五大关键因素，因而土壤的形成是多种因素作用的结果。时空是物质运动的存在形式，事物永远是作为过程而存在。而土壤的形成也不是一蹴而就的，是需要一定的时间持续的作用才最终得以形成。因此，正确选项是ABD。【干扰项辨识】选项C，表述错误，事物的发展是一个螺旋式上升和波浪式前进的过程，而并不是线性过程。因此，排除。必背金句：时空是物质运动存在的形式，运动是物质的根本属性和存在方式。</p>","k":"考点11 物质运动和时空","kid":"114","r":89183,"tot":156108},{"i":"67023","t":"多选","q":"平衡是事物发展的一种状态，小到体操中人在平衡木上的行走，杂技中的骑车走钢丝，独轮车表演，直升机在空中的悬停，大到人类的生存，地球的运转，天体的运行等等，都是保持平衡的一种状态，世间的万事万物，之所以能不停的运动、发展、前进，一个重要原因就在于保持了平衡，要使“平衡”成为人们的“大智慧”，就要","o":{"A":"A.全面理解绝对运动和相对静止的辩证关系","B":"B.准确掌握辩证否定的方式和方向","C":"C.精确把握事物的度","D":"D.善于协调事物内部各种因素的相互关系"},"a":"ACD","j":"<p>[难度系数]0.346本题考查的考点是：矛盾的同一性和斗争性及其在事物发展中的作用，运动和静止，适度原则。题干中所举的例子能保持一种平衡的状态，是因为找到了事物发展状态中的一种和谐的状态，矛盾的双方暂时和谐统一，把握了事物的适度原则，无条件的绝对运动和有条件的相对静止构成了事物的矛盾运动。只有把握了运动和静止的辩证关系，才能正确理解物质世界及其运动形式的多样性，才能理解认识和改造世界的可能性。因此，正确选项是ACD。【干扰项辨识】选项B，辩证否定从形式上看，是螺旋式上升或波浪式前进，方向是前进上升的，与材料中的&ldquo;平衡&rdquo;无关。因此，排除。</p>","k":"考点4 否定之否定规律（唯物辩证法第三规律）","kid":"145","r":53845,"tot":162749},{"i":"67032","t":"多选","q":"《传习录》记载，王阳明与友人曾游南镇，一友指岩中花树问曰：“天下无心外之物，如此花树在深山中自开自落，于我心亦何相关？”先生曰：“你未看此花时，此花与汝心同归于寂;你来看此花时，此花颜色一时明白起来，便知此花不在你的心外。”王阳明这一观点的错误在于（  ）。","o":{"A":"A.把人对花的感觉与花的存在等同起来","B":"B.把人对花的感觉夸大成脱离花的独立实体","C":"C.主张人对花的感觉是主观与客观的统一","D":"D.肯定人对花的感觉的能动性"},"a":"AB","j":"<p>题干中，王阳明的观点在于其唯心主义的认识论。唯心主义认识论否认认识是人脑对客观世界的反映，认为认识先于物质，先于人的实践经验。其中，主观唯心主义认为人的认识是主观自生的，是生而知之的。选项A 中，人对花的感觉是主观的，花的存在是物质，是客观的，两者不等同，所以这是他的错误；选项B 中，人对花的感觉不是自生的，因为不能脱离花的独立实体，这也是他的错误，因此，<strong><span style=\"background-color: #bfedd2;\">正确答案是AB</span></strong>。</p>\n<p>干扰项辨识：</p>\n<p><strong>选项C</strong>，人对花的感觉是意识，意识是主观形式与客观内容的统一，这是正确的观点，因 此，排除。</p>\n<p><strong>选项D</strong>，人对花的感觉是意识，肯定意识的能动性，这是正确的观点，因此，排除。</p>","k":"考点4 认识的本质","kid":"163","r":87237,"tot":154622},{"i":"67034","t":"多选","q":"法国科学家路易•巴斯德说:“在观察事物之际,机遇偏爱有准备的头脑”下列各项与这句话表达的内涵一致的是（  ）。","o":{"A":"A.没有渗透头脑的观察是无意义的","B":"B.感觉到了的东西不能立刻理解它，只有理解了的东西才能深刻地感受它","C":"C.没有理性，眼睛就是最坏的见证者","D":"D.一个除了书本以外一无所知的学者，必然对书本也是无知的"},"a":"ABC","j":"<p>感性认识是认识的低级阶段，是人们在实践基础上通过感觉器官感受到的关于事物的现象、事物的外部联系、事物的各个方面的认识，包括感觉、知觉、表象三种形式。理性认识是认识的高级阶段，是指人们通过抽象思维，在概括整理大量感性材料的基础上，达到关于事物的本质、全体、内部联系和事物自身规律性的认识。题干中的&ldquo;偏爱有准备的头脑&rdquo;正是强调理性认识的重要性。因此，<strong><span style=\"background-color: #bfedd2;\">正确答案是ABC</span></strong>。</p>\n<p>干扰项辨识：</p>\n<p><strong>选项D</strong>，此处强调的是书本之外的感性经验、实践的重要性，不符合题意。因此，排除。</p>","k":"考点5 认识的过程（两次飞跃）","kid":"166","r":50078,"tot":159628},{"i":"67037","t":"多选","q":"列宁也曾以玻璃杯子为例，说明一个物体在不同的人的不同使用中表现出多种不同的价值。同样，药物的价值是治疗疾病，它对病人有价值，对健康人则没有价值。以下说法中正确的是（），","o":{"A":"A.价值的存在取决于人们对它的认识和评价","B":"B.价值直接同主体相联系，始终以主体为中心","C":"C.价值关系不是自然现成的关系，而是一种创造性的关系","D":"D.价值关系是实践的主体和客体相互作用关系中最根本的关系"},"a":"BC","j":"<p>价值的基本特性有：第一，主体性。这是指价值直接同主体相联系，始终以主体为中心。其一，价值关系的形成依赖于主体的存在。其二，价值关系的形成依赖于主体的创造，使客体潜在的价值转化为现实的存在。因此，主客体之间的价值关系不是一种自然的现成关系，而是主体在实践基础上确立的同客体之间的一种创造性的关系。第二，客观性。第三，多维性。第四，社会历史性。因此，<span style=\"background-color: #bfedd2;\"><strong>正确答案是 BC。</strong></span></p>\n<p>干扰项辨识：</p>\n<p><strong>选项A</strong>，表述错误。价值是指在实践基础上形成的主体和客体之间的意义关系，不是取决于人们对它的认识和评价。</p>\n<p><strong>选项D</strong>，表述错误。实践的主体和客体相互作用的关系包括实践关系、认识关系、价值关系，其中实践关系是最根本的关系。因此，排除。</p>","k":"考点12 真理与价值的辩证统一","kid":"177","r":34236,"tot":163581},{"i":"67039","t":"多选","q":"习近平同志指出：“中国共产党人的理想信念，建立在马克思主义科学真理的基础之上，建立在马克思主义揭示的人类社会发展规律的基础之上，建立在为最广大人民谋利益的崇高价值的基础之上。我们坚定，是因为我们追求的是真理。我们坚定，是因为我们遵循的是规律。我们坚定，是因为我们代表的是最广大人民的根本利益。”这说明（  ）。","o":{"A":"A.任何成功的实践都是合规律性和合目的性的统一","B":"B.价值尺度是真理尺度的前提","C":"C.价值尺度推动着人们不断发现新的真理","D":"D.脱离了价值尺度，真理就缺失了主体意义"},"a":"ACD","j":"<p>任何成功的实践都是真理尺度和价值尺度的统一，是合规律性和合目的性的统一。一方面，价值尺度必须以真理尺度为前提。脱离了真理尺度，价值尺度就偏离了合理的、正确的轨道。另一方面，人类自身需要的价值尺度推动着人们不断发现新的真理。脱离了价值尺度，真理就缺失了主体意义。因此，<span style=\"background-color: #bfedd2;\"><strong>正确答案是ACD</strong></span>。</p>\n<p>干扰项辨识：</p>\n<p><strong>选项B</strong>，表述错误，价值尺度必须以真理尺度为前提。因此，排除。</p>","k":"考点12 真理与价值的辩证统一","kid":"177","r":59239,"tot":155516},{"i":"67043","t":"多选","q":"2022年4月，我国科学家独创了一种二氧化碳转化新路径，通过电催化与生物合成相结合，成 功以二氧化碳和水为原料合成了葡萄糖和脂肪酸，为人工和半人工合成“粮食”提供了新路径。这表明","o":{"A":"A.事物本质依赖于人类认识的发现","B":"B.人们可以通过实践，把观念的东西变成现实的东西，创造出新的事物","C":"C.要善于开发和运用创新思维能力，更好地解决社会发展中出现的新问题","D":"D.科研人员的认识活动越来越具有直接现实性"},"a":"BC","j":"<p>我国科学家独创了一种二氧化碳转化新路径，通过电催化与生物合成相结合， 成功以二氧化碳和水为原料合成了葡萄糖和脂肪酸，为人工和半人工合成&ldquo;粮食&rdquo;提供了新路径。这表明人们可以通过实践，把观念的东西变成现实的东西，创造出新的事物，要善于开发和运用创 新思维能力，更好地解决社会发展中出现的新问题。故B、C两项符合题意。</p>\n<p>干扰项辨识：事物的本质是客观的，并不依赖于人的意识，实践具有直接现实性，认识活动没有直接现实性，故 <strong>A、D两项</strong>错误。</p>","k":"考点1 实践的本质和基本特征","kid":"71","r":87345,"tot":150501},{"i":"67044","t":"多选","q":"元宇宙是整合多种新技术而产生的新型虚实相融的互联网应用和社会形态，它基于扩展现实 技术提供沉浸式体验，以及数字孪生技术生成现实世界的镜像，通过区块链技术搭建经济体 系，将虚拟世界与现实世界在经济系统、社交系统、身份系统上密切融合，并且允许每个用户 进行内容生产和编辑。2020年是人类社会虚拟化的临界点，为2021年成为元宇宙元年做了 铺垫。 一方面疫情加速了社会虚拟化，在新冠肺炎疫情防控措施下，全社会上网时长大幅增 长，“宅经济”快速发展；另一方面，线上生活由原先短时期的例外状态成为常态，由现实世界 的补充变成了现实世界的平行世界，人类现实生活开始大规模向虚拟世界迁移，人类成为现 实与数字的“两栖物种”。这说明虚拟实践","o":{"A":"A.可以脱离现实的时间空间而独立存在","B":"B.使当代人类实践的范围越来越广泛而深入","C":"C.实质是主体和客体之间通过数字化中介系统在虚拟空间进行的双向对象化的活动 ","D":"D.是实践活动的派生形式"},"a":"BCD","j":"<p>随着社会的快速发展，当代人类实践出现了新的变化，呈现出许多新的发展特点，实践活动的范围越来越广泛而深入。 一个突出的表现就是，现代信息技术的发展使得当代社会开始产生一种新的实践形式，即虚拟实践。虚拟实践是伴随信息化和网络化发展而产生的，其实质是主体和客体之间通过数字化中介系统在虚拟空间进行的双向对象化的活动，主要活跃于网络世界，具有交互性、开放性、间接性等特点。虚拟实践是实践活动的派生形式，同时又对现实的实践活动产生重大影响。综上可知，本题应选 B、C、D三项。</p>\n<p>干扰项辨识：物质运动总是在一定的时间和空间中进行的，没有离开物质运动的&ldquo;纯粹&rdquo;时间和空间，也没有离开时间和空间的物质运动。故<strong> A 项</strong>错误。</p>","k":"考点11 物质运动和时空","kid":"114","r":117644,"tot":145056},{"i":"67045","t":"多选","q":"万物生长靠太阳。太阳之所以能发光发热，是因为内部的核聚变反应。核聚变能源的原材料 在地球上极其丰富，且排放无污染，如果能造一个“太阳”来发电，人类有望实现能源自由。但  要造出能实用的“人造太阳”,需要上亿摄氏度的等离子体、超过千秒的连续运行时间和1兆  安的等离子体电流，挑战极大。为此，全球范围内科学家们已努力了70多年。2023年4月 12日21时，中国有“人造太阳”之称的全超导托卡马克核聚变实验装置(EAST)  获重大成果， 成功实现了403秒稳态长脉冲高约束模式等离子体运行，创造了托卡马克装置高约束模式运  行新的世界纪录，对探索未来的聚变堆前沿物理问题，提升核聚变能源经济性、可行性，加快  实现聚变发电具有重要意义。\"Shot:122254。\"EAST 控制大厅屏幕上的数字显示，这是历经  12万多次实验取得的成功。材料表明","o":{"A":"A.人的意识不仅反映客观世界，并且创造客观世界","B":"B.人们可以摆脱必然性的制约获得绝对自由","C":"C.科学理论是检验真理的重要标准","D":"D.在发展的实践中才能不断验证认识的真理性"},"a":"AD","j":"<p>万物生长靠太阳。太阳之所以能发光发热，是因为内部的核聚变反应。核聚变能源的原材料在地球上极其丰富，且排放无污染，如果能造一个&ldquo;太阳&rdquo;来发电，人类有 望实现能源自由。说明了人的意识不仅反映客观世界，并且创造客观世界。2023年4月12 日21时，中国有&ldquo;人造太阳&rdquo;之称的全超导托卡马克核聚变实验装置(EAST) 获重大成果，成功实现了403秒稳态长脉冲高约束模式等离子体运行，创造了托卡马克装置高约束模式运行新的世界纪录，对探索未来的聚变堆前沿物理问题，提升核聚变能源经济性、可行性，加快实现聚变发电具有重要意义，这是历经12万多次实验取得的成功。</p>\n<p>干扰项辨识：这说明在发展的实践中不断验证认识的真理性，实践是检验认识真理性的唯一标准，故<strong> C 项</strong>错误。人不能摆脱必然性的制约，只有在认识必然性的基础上才有自由的活动，这就是人的自由限度，也是自由和必然 的辩证规律，故<strong>B 项</strong>也错误。</p>","k":"考点3 实践对认识的决定作用","kid":"73","r":54641,"tot":154354},{"i":"67047","t":"多选","q":"科学实践观的创立和发展具有十分重要的意义，主要表现在","o":{"A":"A.克服了旧唯物主义的根本缺陷，为辩证唯物主义奠定了科学的理论基础","B":"B.建立了科学的、能动的、革命的反映论，实现了人类认识史上的变革","C":"C.在人类思想史上第一次揭示了社会生活的实践本质，为创建科学的历史观奠定了理论基础","D":"D.为人们能动地认识世界和改造世界提供了基本的思想方法和工作方法"},"a":"ABCD","j":"<p>科学实践观的创立和发展具有十分重要的意义，主要表现在：第一，克服了旧唯物主义的根本缺陷，为辩证唯物主义奠定了科学的理论基础。第二，建立了科学的、能动的、革命的反映论，实现了人类认识史上的变革。第三，在人类思想史上第一次揭示了社会生活的实践本质，为创建科学的历史观奠定了理论基础。第四，为人们能动地认识世界和改造世界提供了基本的思想方法和工作方法。故 A、B、C、D四项全选。</p>","k":"考点1 实践的本质和基本特征","kid":"71","r":98311,"tot":145988},{"i":"67050","t":"多选","q":"下列属于辩证唯物主义认识论的观点的是","o":{"A":"A.把论文写在祖国的大地上","B":"B.任何具体真理都带有近似正确的性质","C":"C.没有革命的理论，就不会有革命的运动","D":"D.只要再多走一小步，仿佛是向同一方向迈的一小步，真理便会变成错误"},"a":"ABCD","j":"<p>A 项&ldquo;将论文写在祖国的大地上&rdquo;说明了实践出真知。B 项&ldquo;任何具体真理都带有近似正确的性质\"说明了真理是绝对性与相对性的统一。C 项&ldquo;没有革命的理论，就不会有革命的运动&rdquo;说明了认识对实践的指导作用。 D 项&ldquo;只要再多走一小步，仿佛是向同一方向迈的一小步，真理便会变成错误&rdquo;说明了真理与谬误的对立统一。所以 A、B、C、D四项都是辩证唯物主义认识论观点，故全选。</p>","k":"考点4 认识的本质","kid":"163","r":29777,"tot":157258},{"i":"67051","t":"多选","q":"从实践到认识，认识的过程还没有完成。要实现一个完整的认识过程，还必须由认识再回到 实践中去，实现认识的第二次能动飞跃。从认识到实践的飞跃，是更为重要的飞跃，意义更加 重大，其必要性和重要性在于","o":{"A":"A.认识世界的目的是改造世界","B":"B.认识的真理性只有在实践中才能得到检验和发展","C":"C.感性认识是认识的初级阶段，还不能达到对事物的本质和规律的认识","D":"D.感性认识和理性认识相互渗透、相互包含"},"a":"AB","j":"<p>从认识到实践的飞跃，是更为重要的飞跃，意义更加重大，其必要性和重要性在于以下两方面：第一，认识世界的目的是改造世界。第二，认识的真理性只有在实践中才能得到检验和发展。应选 A、B两项。</p>","k":"考点5 认识的过程（两次飞跃）","kid":"166","r":30615,"tot":158132},{"i":"67060","t":"多选","q":"2021年5月15日7时18分，天问一号探测器成功着陆于火星乌托邦平原南部预选着陆区， 我国首次火星探测任务着陆火星取得成功。目前已在地质年代较年轻的祝融号着陆区发现 了水的活动迹象，表明火星该区域可能含有大量以含水矿物形式存在的可利用水，这为地外 生命的存在提供更多科学依据。早在2300多年前，诗人屈原就用一首长诗《天问》,发出了对 宇宙洪荒、天地自然的疑问。“日月安属?列星安陈?”尽管现代天文学已经可以非常精确地 回答这一问题——太阳系的引力维系着八大行星绕其公转，然而关于生命、人类、太阳系乃至 宇宙的起源，还有太多的未解之谜。但最近5500万公里、最远4亿公里的距离，决定了火星 探测并不轻松。在人类已经进行的40多次火星探测任务中，完全成功的探测任务只有19 次，成功率约43%。这一材料表明","o":{"A":"A.由于主客观条件的限制，人们的实践活动也会达不到自身所期待的结果，导致失败","B":"B.人能够获得关于无限发展着的物质世界的正确认识","C":"C.真理永远处在相对与绝对的相互转化的发展过程中","D":"D.人们的实践活动总是受着真理尺度和价值尺度的制约"},"a":"ABD","j":"<p>近5500万公里、最远4亿公里的距离，决定了火星探测并不轻松。人类进行的40多次火星探测任务中，完全成功的探测任务只有19次，成功率约43%。说明由于主客观条件的限制，人们的实践活动也会达不到自身所期待的结果，导致失败。现代天文学已经可以非常精确地回答这一问题说明世界的可知性，承认人能够获得关于无限发展着的物质世界的正确认识，也就是承认了真理的绝对性。\"人类能否移居火星\"这些思考始终萦绕在人们心头，推动人类对火星的探索，说明人们的实践活动总是受着真理尺度和价值尺度的制约。实践的真理尺度是指在实践中人们必须遵循正确反映客观事物本质和规律的真理。实践的价值尺度是指在实践中人们都是按照自己的尺度和需要去认识世界和改造世界。任何实践活动都是在这两种尺度的共同制约下进行的，任何成功的实践都是真理尺度和价值尺度的统一。故应选 A、B、D三项。</p>\n<p>干扰项辨识：真理永远处在由相对向绝对的转化和发展中，是从真理的相对性走向绝对性、接近绝对性的过程。任何真理性的认识都是由真理的相对性向绝对性转化过程中的一个环节，这是真理发展的规律。故 <strong>C 项</strong>表述错误。</p>","k":"考点12 真理与价值的辩证统一","kid":"177","r":36835,"tot":152719},{"i":"67062","t":"多选","q":"2023年3月29日凌晨2点，中国科学院高能物理研究所与全球40余家科研机构联合发布对 迄今最亮伽马射线暴GRB   221009A的研究成果。高能所牵头研制的慧眼卫星和极目空间望 远镜成功地在硬X 射线和软伽马能段对该伽马暴的瞬时辐射和早期余晖进行了国际最高精 度的测量，不仅发现其具有迄今观测到的最大亮度，将伽马暴的亮度纪录提升了50倍，而且 发现其各向同性能量也打破纪录，相当于在1分钟内释放8个太阳质量的全部能量，还揭示 其产生了极为狭窄、极端明亮、接近光速运动的喷流，对这个千年一遇的天体爆发的研究做出 了独特贡献。这一材料表明","o":{"A":"A.实践提供了日益完备的物质手段，不断强化主体的认识能力","B":"B.认识的最终目的是为了揭示宇宙的奥秘","C":"C.科学实验活动是检验认识是否是真理的唯一标准","D":"D.客观世界及实践的不断发展使人类的认识具有无限性"},"a":"AD","j":"<p>高能所牵头研制的慧眼卫星和极目空间望远镜成功地在硬 X 射线和软伽马能段对该伽马暴的瞬时辐射和早期余晖进行了国际最高精度的测量表明实践提供了日益完备的物质手段，不断强化主体的认识能力，故A 项正确。此次探测不仅将伽马暴的亮度纪录提升了50倍，而且发现其各向同性能量也打破纪录，相当于在1分钟内释放8个太阳质量的全部能量，还揭示其产生了极为狭窄、极端明亮、接近光速运动的喷流，说明客观世界及实践的不断发展使人类的认识具有无限性。故D 项正确。</p>\n<p>干扰项辨识：</p>\n<p>认识的最终目的是为了指导实践，改造客观世界，故<strong>B 项</strong>错误。实践是检验认识是否是真理的唯一标准，故<strong>C 项</strong>错误。本题应选 A、D两项。</p>","k":"考点6 认识过程中的影响因素（理性因素和非理性因素）","kid":"167","r":92730,"tot":141652},{"i":"67063","t":"多选","q":"基础研究是“根科学”,是科学体系的源头，处于从研究到应用、再到生产的科研链条起始端。 通过基础研究，才能变不确定性为确定性，变未知为已知。从来没有百分之百成功的基础研 究。只有宽容失败，才有从容探索；没有大量错误作台阶，也就登不上最后正确结果的高座。 对于“失败”的每一次宽容，都在涵养敢担风险、勇攀高峰的科研生态，孕育下一次创新的成 功。而一旦“慢跑”中的科学家拨动到灵感的琴弦，看似“无用”的原始创新成果就能如核裂变 般爆发出巨大能量，推动文明进程的跨越式发展，以浩荡之势开辟崭新天地。这在认识论上的启示是","o":{"A":"A.由于真理具有反复性，人们探索真理的过程不会一帆风顺","B":"B.非理性因素对于人的认识能力和认识活动具有激活、驱动作用","C":"C.只有经过多次失败，不断纠错，才能实现主客观的统一，在实践中得到预想的结果 ","D":"D.真理要以谬误为基础，总是与谬误相伴而行"},"a":"BC","j":"<p>科学家拨动到灵感的琴弦，看似\"无用\"的原始创新成果就能如核裂变般爆发出巨大能量，说明非理性因素对于人的认识能力和认识活动具有激活、驱动作用。对于&ldquo;失败&rdquo;的每一次宽容，都在涵养敢担风险、勇攀高峰的科研生态，孕育下一次创新的成功。这说明只有经过多次失败，不断纠错，才能实现主客观的统一，在实践中得到预想的结果。故本题应选B、C两项。</p>\n<p>干扰项辨识：</p>\n<p><strong>A 项</strong>错在真理具有反复性上，应该是认识具有反复性。</p>\n<p><strong>D 项</strong>错在真理要以谬误为基础上，真理是对客观事物及规律的正确认识，与谬误有本质区别，不会以错误为基础。</p>","k":"考点6 认识过程中的影响因素（理性因素和非理性因素）","kid":"167","r":40549,"tot":150474},{"i":"67065","t":"多选","q":"面对层出不穷的新问题、新挑战，我们要“知行相资以为用”,不断深化认识、总结经验，实现理论创新和实践创新良性互动，把党和国家事业推向新的高度。下列古语与“知行相资以为用” 蕴含的哲理一致的是","o":{"A":"A.行有不慊于心，则馁矣(《孟子 ·公孙丑上》)","B":"B.行可兼知，而知不可兼行(《尚书引义 ·说命中》)","C":"C.知行常相须，如目无足不行，足无目不见(《朱子语类》卷九)","D":"D.事莫明于有效，论莫定于有证。空言虚语，虽得道心，人犹不信(《论衡 ·薄葬篇》）"},"a":"CD","j":"<p>&ldquo;知行相资以为用&rdquo;体现了实践和认识的辩证关系，实践是认识的基础，认识对实践有指导作用，要做到理论与实践具体的历史的统一。&ldquo;知行常相须，如目无足不行，足无目不见&rdquo;&ldquo;事莫明于有效，论莫定于有证。空言虚语，虽得道心，人犹不信&rdquo;都强调了理论与实践的辩证关系，故C、D两项符合题意。</p>\n<p>干扰项辨识：</p>\n<p>行有不慊于心，则馁矣，这句话的意思是说人在言行中总感觉不满意不知足，就会泄气气馁，故 <strong>A 项</strong>与题意不符。</p>\n<p>行可兼知，而知不可兼行这强调了实践决定认识，有其合理之处，但是否认了认识反作用于实践，<strong>B项</strong>与题意不符。</p>","k":"","kid":"","r":51353,"tot":147025},{"i":"67067","t":"多选","q":"物联网是通过信息传感设备将各种物品与互联网连接起来，实现物品的自动识别、定位、跟踪、控制和信息的互联共享。近几年来，物联网技术开始越来越广泛地应用于经济和社会生活之中。这表明","o":{"A":"A.人们可以根据自己的主观要求创造事物间的联系","B":"B.联系具有普遍性，事物之间的联系形式是多样的","C":"C.人类可以根据事物固有的联系建立新的具体联系","D":"D.事物间的联系因具有“人化”的特点进而主观化"},"a":"BC","j":"<p>本题考查联系的观点。联系的普遍性是指世界上的任何事物都不能孤立地存在，都同周围的其他事物联系着；每一事物各个要素也不能孤立地存在，都同其他要素联系着；整个世界就是一个相互联系的有机整体。而<span style=\"color: #e03e2d;\">联系的形式是多样的，&ldquo;物联网是通过信息传感设备将各种物品与互联网连接起来，实现物品的自动识别、定位、跟踪、控制和信息的互联共享&rdquo;，表明了联系的普遍性，也表明了联系是客观的，但人们可以根据事物固有的联系建立新的具体联系</span>。因此，<strong>选项B、C正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项A</strong>，抓住关键词&ldquo;创造&rdquo;即可判断该选项说法错误，违背了联系的客观性。联系是客观的，是客观事物所固有的属性，是不以人的意志为转移的客观存在，而不是外部强加给事物的或主观臆造的。故不选。</p>\n<p><strong>选项D</strong>，联系是客观的，在任何情况下都不会被主观化，主观臆造联系是错误的。故不选。</p>","k":"考点1 唯物辩证法两大总特征","kid":"68","r":72937,"tot":144068},{"i":"67068","t":"多选","q":"《国语•郑语》中有一句话：“夫和实生物，同则不继。以他平他谓之和，故能丰长而物归之。若以同裨同，尽乃弃矣。”这句话蕴含的辩证法思想有","o":{"A":"A.矛盾的同一是包含差别的同一","B":"B.对立面的统一是事物发展的动力","C":"C.不包含内部差别的事物就不能存在和发展","D":"D.矛盾的一方只有克服另一方才能达到统一"},"a":"ABC","j":"<p>本题考查辩证法的相关内容。本题题干的意思是&ldquo;<span style=\"color: #e03e2d;\">和谐才是创造事物的原则，完全一致的事物是不能存在和发展的。把许多不同的东西结合在一起而使它们得到平衡，这叫作和谐，所以能够使物质丰盛而成长起来。如果以相同的东西加合在一起，便会被抛弃了&rdquo;。</span>也就是说，&ldquo;和&rdquo;是不同元素的结合不同、差别是&ldquo;和&rdquo;的前提，这样的&ldquo;和&rdquo;才能长久，合成的物才能&ldquo;丰长&rdquo;。如果&ldquo;去和取同&rdquo;，以此治国，就会排斥异己、独断专行，这就离灭亡不远了。这说明矛盾的同一是包含差别的同一，对立面的统一是事物发展的动力，不包含内部差别的事物就不能存在和发展。因此，<strong>选项A、 B、C正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项D</strong>，错在关键词&ldquo;只有&rdquo;二字。矛盾的一方克服另一方达到统一是解决矛盾的一种形式，但不是唯一的形式。事实上，矛盾解决的形式是多种多样的。故不选。</p>","k":"考点2 对立统一规律（唯物辩证法第一规律）","kid":"69","r":66313,"tot":141659},{"i":"67069","t":"多选","q":"《史记•孙子吴起列传第五》中记载了“田忌赛马”的故事，齐国大将田忌经常与齐国众公子赛马，设重金赌注。孙膑发现他们的马脚力都差不多，马分为上、中、下三等，于是便对田忌说：“您只管下大赌注，我能让您取胜。”田忌相信并答应了他，与齐威王和各位公子用千金作赌注。比赛即将开始，孙膑说：“现在用您的下等马对付他们的上等马，用您的上等马对付他们的中等马，用您的中等马对付他们的下等马。”三场比赛结束后，田忌一场败而两场胜，最终赢得千金赌注。因此田忌把孙膑推荐给齐威王。齐威王向他请教兵法，并封他为军师。这个故事给我们的启示有","o":{"A":"A.任何事物的内容都有一定的表现形式","B":"B.当形式适合内容时，对内容的发展起着积极的推动作用","C":"C.形式的变化对内容的发展起着决定性的作用","D":"D.可以利用、改造和创造必要的形式为内容服务"},"a":"ABD","j":"<p>本题考查内容与形式的辩证关系。田忌赛马的故事体现的是内容和形式的辩证关系。上、中、下三等马是内容，而它们按什么顺序出场、按什么结构编排，则是形式。<span style=\"color: #e03e2d;\">任何事物的内容都有一定的表现形式，内容是构成事物的一切要素的总和，是事物存在的基础；形式是内容诸要素相互结合的结构和表现方式。</span>选项A正确。<span style=\"color: #e03e2d;\">当形式适合内容时，对内容的发展起着积极的推动作用；当形式不适合内容时，对内容的发展起着消极的阻碍作用。</span>选项B正确。可以根据内容的需要决定形式的取舍、改造和创新，利用和创造必要的形式，发挥形式的积极作用为内容服务。选项D正确。因此，<strong>选项A、B、D正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项C</strong>，说法错误。形式的变化可以影响内容的发展，但不能决定其发展。辩证法告诉我们，内容决定形式，形式反作用于内容。故不选。</p>","k":"考点5 内容和形式（唯物辩证法第一对基本范畴）","kid":"147","r":92194,"tot":138030},{"i":"67070","t":"多选","q":"恩格斯指出：“物质的任何有限的存在方式，不论是太阳或星云，个别的动物或动物种属，化学的化合或分解，都同样是暂时的，而且除永恒变化着、永恒运动着的物质以及这一物质运动和变化所依据的规律外，再没有什么永恒的东西了。”在永恒存在着的世界上，任何事物都是暂时的，任何事物都是由其他事物转化而来的，并且必将转化为另外的事物。由此可见，事物是由可能到现实的过程。这给我们的启示是","o":{"A":"A.没有可能就没有现实","B":"B.可能包含着现实的因素和根据","C":"C.抽象的可能也必将实现","D":"D.事物发展一定是好的可能"},"a":"AB","j":"<p>本题考查现实与可能的关系。<span style=\"color: #e03e2d;\">现实和可能既有区别又有联系。没有现实就没有可能，反过来，没有可能就没有现实，它们在一定条件下相互转化。</span>选项A正确。<span style=\"color: #e03e2d;\">可能与现实具有辩证关系：一方面，现实蕴藏着未来的发展方向，会不断产生新的可能；另一方面，可能包含着发展成为现实的因素和根据，一旦主客观条件成熟，可能就转化为现实。</span>选项B正确。因此，<strong>选项A、B正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项C</strong>，现实的可能是理论上可行，也具有实现的现实条件；而抽象的可能是理论上可行，但缺乏现实条件。所以&ldquo;抽象的可能也必将实现&rdquo;说法错误，故不选。</p>\n<p><strong>选项D</strong>，说法错误。事物的发展不仅有好的可能，也有不好的可能。请注意，这里所谓的&ldquo;好的可能&rdquo;是针对作为主体的人来说的，也就是对人是否有利。此处考生可能会混淆。因为辩证法的发展观认为，发展就是向上的运动和顺应规律的变化，即事物的发展指的是向好的方面变化。那为什么关于选项D还存在着不好的可能呢？关键就在于，&ldquo;事物的发展是向好的方面变化&rdquo;，此处的&ldquo;好&rdquo;是符合、顺应规律的意思，而&ldquo;事物的发展不仅有好的可能，也有不好的可能&rdquo;，此处的&ldquo;好&rdquo;是对人是否有利的意思。</p>","k":"考点9 可能和现实（唯物辩证法第五对基本范畴）","kid":"154","r":89471,"tot":138959},{"i":"67074","t":"多选","q":"中国古代思想家荀子的《劝学》中有句名言：“不积跬步，无以至千里；不积小流，无以成江海。”这句话强调了","o":{"A":"A.事物的发展是一个不断量变的过程","B":"B.事物的发展是一个不断质变的过程","C":"C.量变是质变的必要准备","D":"D.质变是量变的必然结果"},"a":"AC","j":"<p>本题考查量变与质变的辩证关系。这句话的意思：千里之路，要靠一步步走出来；浩瀚江海，要靠无数小溪流汇集而成。其蕴含的哲理是量变与质变的辩证关系原理。<span style=\"color: #e03e2d;\">事物的发展总是从量变开始，量变是质变的前提和必要准备，质变是量变的必然结果。事物的发展就是这样由量变到质变，又在新质的基础上开始新的量变，如此循环，不断前进</span>。因此，<strong>选项A、C正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项B</strong>，说法错误。事物的量变体现的是事物发展的连续性，因此是一个&ldquo;不断&rdquo;的过程；而事物的质变体现的是事物发展连续性的中断，因此不能说&ldquo;不断质变&rdquo;。故不选。</p>\n<p><strong>选项D</strong>，说法正确，但是本题题干强调的是量变，而不是质变，故不选。</p>","k":"考点3 量变质变规律（唯物辩证法第二规律）","kid":"143","r":35919,"tot":147277},{"i":"67077","t":"多选","q":"“三坊七巷”是福州市的重点文物古街。福州市政府在三坊七巷的改造过程中坚持在保持三坊七巷过去的历史和文化、经济繁荣景象的同时，又融入了现代化文明城市的元素。这体现的哲学原理有","o":{"A":"A.辩证否定是事物发展的环节","B":"B.辩证否定的实质是“扬弃”","C":"C.创新就是打破一切过去的规则，重新开始","D":"D.辩证否定是事物联系的环节"},"a":"ABD","j":"<p>本题考查辩证的否定观。事物内部都存在着肯定因素和否定因素。肯定因素是维持现存事物存在的因素，否定因素是促使现存事物灭亡的因素。<span style=\"color: #e03e2d;\">否定是事物发展的环节，它是旧事物向新事物的转变，是从旧质到新质的飞跃</span>。只有经过否定，旧事物才能向新事物转变。<span style=\"color: #e03e2d;\">辩证否定的实质是&ldquo;扬弃&rdquo;（取其精华、弃其糟粕），即新事物对旧事物既批判又继承，既克服其消极因素又保留其积极因素。题干中的做法既继承了过去的历史传统又增加了现代化元素。否定是新旧事物联系的环节，新事物产生于旧事物，新旧事物是通过否定环节联系起来的</span>。因此，<strong>选项A、B、D正确</strong>。</p>\n<p>干扰选项：</p>\n<p><strong>选项C</strong>，创新是在过去的基础上，保留积极的东西，丢弃消极的东西，向前发展，而不是打破一切过去的规则。故不选。</p>","k":"考点4 否定之否定规律（唯物辩证法第三规律）","kid":"145","r":80668,"tot":139196},{"i":"67089","t":"多选","q":"下列关于实践本质的说法正确的有","o":{"A":"A.实践是人类适应自然的物质活动","B":"B.实践是主体能动地认识和改造客体的物质活动","C":"C.实践是“知行合一”的活动","D":"D.实践是主观见之于客观的物质活动"},"a":"BD","j":"<p><strong>本题考查实践的本质。</strong>实践是人类能动地改造世界的社会性的物质活动。实践的本质也可以表述为主体能动地认识 和改造客体的物质活动，或主观见之于客观的物质活动。因此，<strong>选项 B、D 正确。</strong></p>\n<p>干扰项分析：</p>\n<p><strong>选项A</strong>, 把人的实践活动仅仅理解为对自然的适应，是把人的实践活动降低为动物的本能活 动，没有看到人对客观世界的积极改造。</p>\n<p><strong>选项C,</strong> &ldquo;知行合一&rdquo;忽视了知行的差别，颠倒了知行的先后次序。</p>","k":"考点1 实践的本质和基本特征","kid":"71","r":21121,"tot":151992},{"i":"67090","t":"多选","q":"认识是主体在实践基础上对客体的能动反映，其主要内容包括","o":{"A":"A.认识是主体对客体的反映","B":"B.主体对客体的反映是一个能动的创造性过程","C":"C.认识是实践的基础和来源","D":"D.主体对客体的能动反映是以实践为中介的"},"a":"ABD","j":"<p><strong>本题考查认识的本质。</strong>认识是主体在实践基础上对客体的能动反映，</p>\n<p>主要内容有：</p>\n<p>第一，坚持了唯物主义反映论的 原则，认为认识是主体对客体的反映；</p>\n<p>第二，主体对客体的反映是一个能动的创造性过程；</p>\n<p>第三，主体对客体的能动反映是以实践为中介的。因此，<strong>选项A、B、D 正确。</strong></p>\n<p>干扰项分析：<strong>选项C</strong>, 表述错误，实践是认识的基础和来源。</p>","k":"考点4 认识的本质","kid":"163","r":70494,"tot":140363},{"i":"67091","t":"多选","q":"认识运动之所以要经过“实践一认识一再实践一再认识”的多次反复，是因为","o":{"A":"A.事物矛盾的暴露是一个过程","B":"B.事物本身的复杂性","C":"C.人们的认识受到主体的立场、观点和方法的限制","D":"D.人们的实践及其认识条件的历史性"},"a":"ABCD","j":"<p><strong>本题考查实践与认识的辩证运动及其规律。</strong>人们对复杂事物的正确认识，往往需要经过多次反复才能完成。这是由于人们的认识总要受 到客观条件和主观条件的限制。四个选项就是对主客观条件的展开。因此，<strong>选项A、B、C、D 正确。</strong></p>","k":"考点7 认识的两大规律（反复性和无限性）","kid":"168","r":67536,"tot":140993},{"i":"67092","t":"多选","q":"绝对真理和相对真理是辩证统一的，表现在","o":{"A":"A.相对真理中包含着绝对真理的颗粒","B":"B.无数相对真理的总和就是绝对真理","C":"C.真理是一个由相对真理走向绝对真理的过程","D":"D.绝对真理存在于相对真理之中"},"a":"ABCD","j":"<p><strong>本题考查真理的绝对性和相对性的辩证关系。</strong>真理的绝对性和相对性是辩证统一的。</p>\n<p>第一，二者相互依存、相互联结。任何真理都既有绝 对性，又有相对性，都是绝对性和相对性的统一。</p>\n<p>第二，二者相互包含。真理的绝对性寓于 真理的相对性之中，真理的相对性必然包含并表现着真理的绝对性。&ldquo;无数相对的真理之总 和，就是绝对的真理。&rdquo;</p>\n<p>第三，二者辩证转化。真理永远处在由相对向绝对的转化和发展中， 任何真理性的认识都是由真理的相对性向绝对性转化过程中的一个环节。因此，<strong>选项A、B、 C、D 正确。</strong></p>","k":"考点9 真理及其特性","kid":"171","r":32741,"tot":146464},{"i":"67093","t":"多选","q":"马克思主义认识论与唯心主义认识论的区别在于，是否承认","o":{"A":"A.认识发展的辩证过程                   ","B":"B.客观事物是认识的对象","C":"C.认识起源于经验                      ","D":"D.社会实践是认识的基础"},"a":"BD","j":"<p><strong>本题考查马克思主义认识论与唯心主义认识论的区别。</strong>马克思主义认识论即辩证唯物主义认识论，把实践的观点引入认识论，把辩证法应用于反映 论，科学地揭示了认识过程中的多方面的辩证关系。选项 B 是唯物主义观点，是马克思主义认识论与唯心主义认识论的区别。选项D 是马克思主义认识论的观点，实践是认识的基础。 因此，<strong>选项 B、D 正确。</strong></p>\n<p>干扰项分析：</p>\n<p><strong>选项A,</strong> 是马克思主义认识论与部分唯心主义认识论都承认的。</p>\n<p><strong>选项C</strong>, 是唯心主义认识论和马克思主义认识论都承认的观点，只是唯心主义的经验和唯物 主义的经验不同。唯心主义认为经验是主观自生的，或是上帝赋予的，更多指的是先天经验， 而否认经验的客观来源(即否认其来源于实践);马克思主义认识论认为，经验来源于实践， 这一经验更多指的是在实践中产生的直接经验。</p>","k":"考点8 实践和认识是具体的历史的统一","kid":"169","r":30328,"tot":149767},{"i":"67094","t":"多选","q":"马克思主义哲学中的辩证法、认识论、历史观在本质上是一致的，体现这种一致性的公式有 ","o":{"A":"A.个别—一般一个别                     ","B":"B.实践一认识一实践","C":"C.群众一领导一群众                     ","D":"D.团结一批评一团结"},"a":"ABC","j":"<p><strong>本题考查列宁关于&ldquo;辩证法也就是(黑格尔和)马克思主义的认识论&rdquo;的观点。</strong>本题运用列宁关于&ldquo;辩证法也就是(黑格尔和)马克思主义的认识论&rdquo;的观点提出体现辩证 法、认识论、历史观本质上一致的公式。</p>\n<p><strong>选项A </strong>体现辩证法，<strong>选项B </strong>体现认识论，<strong>选项C </strong>体 现历史观。三者的一致性是指<strong>选项A </strong>是世界观，<strong>选项 B </strong>是对<strong>选项A</strong> 在认识过程的运用与体 现，<strong>选项C</strong> 是对<strong>选项A、B </strong>在历史观中的运用与体现。因此，<strong>选项A、B、C</strong> 正确。</p>\n<p>干扰项分析：<strong>选项D</strong>, 是毛泽东提出的正确处理人民内部矛盾的方法，即&ldquo;从团结的愿望出发，经过批评与自我批评，在新的基础上达到新的团结&rdquo;。</p>","k":"考点8 实践和认识是具体的历史的统一","kid":"169","r":27074,"tot":147034},{"i":"67105","t":"多选","q":"恩格斯指出：“人们周围的、至今统治着人们的生活条件，现在受人们的支配和控制，人们第一次成为自然界的自觉的和真正的主人，因为他们已经成为自身的社会结合的主人了。人们自己的社会行动的规律，这些一直作为异己的、支配着人们的自然规律而同人们相对立的规律，那时就将被人们熟练地运用，因而将听从人们的支配。人们自身的社会结合一直是 作为自然界和历史强加于他们的东西而同他们相对立的，现在则变成他们自己的自由行动了。至今一直统治着历史的客观的异己的力量，现在处于人们自己的控制之下了。只是从这时起，人们才完全自觉地自己创造自己的历史；只是从这时起，由人们使之起作用的社会原因才大部分并且越来越多地达到他们所预期的结果。这是人类从必然王国进入自由王国的飞跃。”这段话说明","o":{"A":"A.自由就是摆脱自然规律达到意志和精神力量的绝对自由","B":"B.人类社会的最终发展目标是自由意志主宰世界","C":"C.人类能动的改造世界的过程就是必然王国走向自由王国的过程","D":"D.自由是对必然的认识和对世界的改造"},"a":"CD","j":"<p><strong>本题考查自由王国和必然王国。</strong>题干中，恩格斯的话反映了人类认识世界和改造世界的实践活动既是自由的基础，也是实现自 由的条件，人的自由就是在活动中通过认识和利用必然所表现的一种自觉、自为、自主的状 态。自由是对必然的认识，人不能摆脱必然的制约，也不能超出必然所限定的范围去寻找自 由。认识必然并不等于达到了自由，只有利用必然改造世界，达到预想的目的，才是真正得到 了自由。人类历史就是一个不断地从必然王国向自由王国发展的历史。因此，<strong>选项 C、D 正确。</strong></p>\n<p>干扰项分析：<strong>选项A、B</strong>, 属于唯心主义的观点。</p>","k":"考点15 从必然走向自由","kid":"180","r":108349,"tot":134464},{"i":"67109","t":"多选","q":"实践之所以是检验真理的唯一标准，是因为实践","o":{"A":"A.具有直接现实性的特点                 ","B":"B.是主观见之于客观的活动","C":"C.具有普遍性的特点                    ","D":"D.是联系主观和客观的“桥梁”"},"a":"ABCD","j":"<p><strong>本题考查实践的特点。</strong>实践是主观见之于客观的物质活动，是沟通主观和客观的&ldquo;桥梁&rdquo;,它不仅具有普遍性的特点，而且具有直接现实性的特点。四个选项都是列宁和毛泽东的经典原话，记住正确说法即 可。因此，<strong>选项A、B、C、D 正确。</strong></p>","k":"考点11 真理的检验标准","kid":"175","r":53953,"tot":145126}]};
